
const KEY='save-cash-v2';const TODAY=()=>{const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jerusalem',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(x=>[x.type,x.value]));return p.year+'-'+p.month+'-'+p.day};let d=CashModel.migrate();let ready=false;let scratchCounter=0;const scratchStates={};let testValue=0;

function storageError(e){document.getElementById('storage-state').textContent='Не удалось сохранить: '+e.message+' · экспортируйте полную ZIP-копию';}
const fmt=n=>Number(n||0).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2})+' ₪';const sum=CashModel.total;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const id=()=>crypto.randomUUID();const cibus=()=>CashModel.cibus(d).amount;const child=()=>CashModel.child(d);const totalSub=()=>sum(d.subs.filter(x=>x.active!==false&&!x.deleted&&CashModel.belongs(d,x)));const purchasesCash=()=>sum(CashModel.unique(d.purchases).filter(x=>CashModel.method(x.method)==='debit'&&CashModel.inPeriod(d,x.date)&&CashModel.belongs(d,x)));const purchasesCard=()=>sum(CashModel.unique(d.purchases).filter(x=>CashModel.method(x.method)==='credit'&&CashModel.inPeriod(d,x.date)&&CashModel.belongs(d,x)&&CashModel.belongs(d,x)));const planned=()=>sum(d.planned.filter(x=>!x.deleted&&CashModel.belongs(d,x)));const holiday=()=>sum(d.holidays.filter(x=>!x.deleted&&CashModel.belongs(d,x)));const expenses=()=>CashModel.calculate(d).expenses;const forecast=()=>CashModel.calculate(d).forecast;const free=()=>CashModel.calculate(d).free;const item=(label,value,color='')=>`<div class="row"><span>${label}</span><span class="money ${color}">${fmt(value)}</span></div>`;
const PANEL_GROUPS={cibus:'cibus',child:'child',subs:'payments',installments:'payments',holidays:'plans',planned:'plans',purchases:'purchases',forecast:'payments',chart:'analysis',bankrecon:'payments',creditloans:'payments',menora:'payments',dog:'dog',reconciliation:'analysis'};
let currentView='home';let viewExpanded={};
function expanded(key){return currentView==='home'?!!d.open[key]:(viewExpanded[key]??true)}
function section(key,title,content,total=''){return `<section class="card app-panel" data-panel="${PANEL_GROUPS[key]}" data-section="${key}"><div class="section-head" onclick="toggle('${key}')"><h2>${title}</h2><div><b>${total}</b> <span data-caret>${expanded(key)?'⌃':'⌄'}</span></div></div><div class="section-body" ${expanded(key)?'':'hidden'}>${content}</div></section>`}
function navigationHTML(){return `<nav class="budget-navigation" aria-label="Разделы бюджета"><button class="back-home" id="backHome" onclick="goView('home')" hidden>← Назад</button><div class="budget-tabs" id="budgetTabs">${[['purchases','Покупки','cart'],['payments','Платежи','card'],['child',d.childName==='ребёнок'?'Максим':d.childName||'Максим','family'],['cibus','Cibus','meal'],['plans','Планы','calendar'],['analysis','Расчёты','chart'],['dog','Собака','paw'],['all','Все блоки','blocks']].map(([key,label,icon])=>`<button class="budget-tab" data-view="${key}" aria-pressed="false" onclick="goView('${key}')">${navigationIcon(icon)}<span>${esc(label)}</span></button>`).join('')}</div></nav>`}
function navigationIcon(name){const paths={paw:'<ellipse cx="12" cy="16" rx="6" ry="5"/><ellipse cx="4" cy="9" rx="2" ry="3"/><ellipse cx="9" cy="5" rx="2" ry="3"/><ellipse cx="15" cy="5" rx="2" ry="3"/><ellipse cx="20" cy="9" rx="2" ry="3"/>',cart:'<path d="M3 3h2l3 12h10l3-9H6M9 20h.01M18 20h.01"/>',card:'<rect x="2" y="4" width="20" height="16" rx="3"/><path d="M2 9h20M6 15h4"/>',family:'<circle cx="9" cy="7" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3m2-15a3 3 0 0 1 0 6m1 3a5 5 0 0 1 3 5v1"/>',meal:'<path d="M4 3v6a3 3 0 0 0 6 0V3M7 3v18M17 3c-3 4-3 8 1 9v9m0-18v9"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 2v6m10-6v6M3 11h18m-13 5h.01m4 0h.01m4 0h.01"/>',chart:'<path d="M3 3v18h18M7 16v-4m5 4V8m5 8V5"/>',blocks:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>'};return '<svg class="ui-svg" viewBox="0 0 24 24" aria-hidden="true">'+paths[name]+'</svg>'}
function goView(key){if(!['home','all','purchases','payments','child','cibus','plans','analysis','dog'].includes(key))return;currentView=key;viewExpanded={};applyNavigation();window.scrollTo({top:0,behavior:'instant'})}
function applyNavigation(){const root=document.getElementById('app');root.querySelectorAll('[data-panel]').forEach(panel=>{const group=panel.dataset.panel;panel.hidden=currentView!=='all'&&group!==currentView});document.getElementById('budgetTabs').hidden=currentView==='all';document.getElementById('backHome').hidden=currentView==='home';root.querySelectorAll('[data-view]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.view===currentView)));root.querySelectorAll('[data-section]').forEach(panel=>{const open=expanded(panel.dataset.section);panel.querySelector('.section-body').hidden=!open;panel.querySelector('[data-caret]').textContent=open?'⌃':'⌄'})}

