function categoryReportHTML(){let cats={};for(let x of CashModel.unique(d.purchases).filter(x=>CashModel.inPeriod(d,x.date)&&CashModel.belongs(d,x))){(cats[x.category||'Другое']??=[]).push(x)}return `<div class="actions"><button class="compact" onclick="document.querySelectorAll('.cat').forEach(x=>x.open=true)">Развернуть все</button><button class="compact" onclick="document.querySelectorAll('.cat').forEach(x=>x.open=false)">Свернуть все</button></div><div class="gray">${item('Обязательные платежи',Number(d.rent)+(d.loanActive?Number(d.loan):0))}${item('Алименты и ребёнок',child())}${item('Абонплаты',totalSub())}</div>${Object.entries(cats).map(([name,items])=>`<details class="cat"><summary><b>${esc(name)} · ${fmt(sum(items))}</b></summary>${items.map(x=>`<div class="purchase row"><span>${esc(x.name)}<div class="small">${esc(x.date)} · ${esc(methodLabel(x.method))} · ${esc(x.status)}</div>${x.document_id||x.attachment?`<button class="compact" onclick="viewReceipt('${x.id}')">Чек</button>`:''}${x.receipt_items?.length?`<details class="small"><summary>Товары (${x.receipt_items.length})</summary>${x.receipt_items.map(v=>`<div class="receipt-item"><span dir="auto">${esc(v.name)}</span><span>${fmt(v.amount)}</span></div>`).join('')}</details>`:''}</span><div class="field"><b>${fmt(x.amount)}</b><button class="icon" onclick="editPurchase('${x.id}')">✎</button><button class="icon danger" onclick="removeItem('purchases','${x.id}')">×</button></div></div>`).join('')}</details>`).join('')||'<div class="empty">Покупок пока нет</div>'}`}
function toggle(k){if(PANEL_GROUPS[k]&&currentView!=='home')viewExpanded[k]=!expanded(k);else d.open[k]=!d.open[k];save();render()}function set(k,v){d[k]=typeof d[k]==='boolean'?Boolean(v):Number(v)||0;save();render()}function edit(k){const e=document.getElementById('field-'+k);if(!e)return;e.classList.add('editing');e.querySelector('input')?.focus()}function commit(k,v){const n=Number(v);if(!Number.isFinite(n)||(!['limit','balance'].includes(k)&&n<0)){render();return}d[k]=n;if(k.startsWith('cibus')){const c=CashModel.cibus(d);d.cibusDays=c.days;d.cibus50=c.n50;d.cibusOrdinary=c.ordinary;}save();render()}function editItem(id){const e=document.getElementById('item-'+id);e.classList.add('editing');e.querySelector('input').focus()}function commitItem(c,id,v){if(!Number.isFinite(Number(v))||Number(v)<0){render();return}let x=d[c].find(x=>x.id===id);if(x)x.amount=Number(v)||0;save();render()}function addItem(c){const names={extra:'Дополнительный расход',subs:'Абонплата',holidays:'Праздничная покупка',planned:'Запланированная покупка'};let opts=c==='holidays'?`<select id="modalType"><option>День рождения</option><option>Новый год</option><option>Особая дата</option><option>Другое</option></select>`:'';modal(`<h3>${names[c]}</h3>${opts}<div class="form-row"><label>Название</label><input id="modalName" placeholder="Название" style="width:100%"></div><div class="form-row"><label>Сумма, ₪</label><input id="modalAmount" type="number" value="0" style="width:100%"></div>${['planned','holidays'].includes(c)?`<div class="form-row"><label>Дата</label><input type="date" id="modalDate" value="${TODAY()}"></div>`:''}<div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="saveItem('${c}')">Добавить</button></div>`)}function saveItem(c){if(!(Number(document.getElementById('modalAmount').value)>=0)||!Number.isFinite(Number(document.getElementById('modalAmount').value)))return;const name=document.getElementById('modalName').value.trim()||document.getElementById('modalType')?.value||'Без названия';d[c].push({id:id(),name,amount:Number(document.getElementById('modalAmount').value)||0,date:document.getElementById('modalDate')?.value,type:document.getElementById('modalType')?.value,source:'Ручной ввод',included_in_statement:false});save();closeModal();render()}function modal(html){document.getElementById('overlay').innerHTML=`<div class="modal-cover" onclick="if(event.target===this)closeModal()"><div class="modal" role="dialog" aria-modal="true">${html}</div></div>`;compactSelects(document.querySelector('.modal'))}function closeModal(){document.getElementById('overlay').innerHTML=''}function confirmSmall(title,yes){window._confirm=yes;modal(`<h3>${title}</h3><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="closeModal();window._confirm()">Подтвердить</button></div>`)}let pay='Ашрай';function choosePay(v){if(v==='Счёт'){confirmSmall('Подтвердить оплату со счёта?',()=>{pay=v;document.getElementById('pay-cash').classList.add('primary');document.getElementById('pay-card').classList.remove('primary')})}else{pay=v;document.getElementById('pay-card').classList.add('primary');document.getElementById('pay-cash').classList.remove('primary')}}const shops=['Шуферсаль','Shufersal','Tiv Taam','Тив Таам','TIFF','Super-Pharm','Супер-Фарм','Rami Levy','Рами Леви','Victory','Виктори','Yochananof','Йохананоф','AM:PM','Арома','Aroma','Макдональдс','McDonald’s','KSP','IKEA','Икеа','Fox','H&M','ZARA','BESTEC','Gold Love'];function suggest(v){const box=document.getElementById('suggestions'),q=String(v).normalize('NFKC').toLocaleLowerCase().trim();box.replaceChildren();if(!q)return;const norm=x=>String(x).normalize('NFKC').toLocaleLowerCase().replace(/[\s־-]/g,''),names=[...d.purchases.filter(x=>!x.deleted).map(x=>x.merchant||x.name),...(d.stores||[]).map(x=>typeof x==='string'?x:x.name),...shops,'שופרסל','סופר-פארם'];const seen=new Set;for(const name of names){if(!name||seen.has(norm(name))||!norm(name).includes(norm(q)))continue;seen.add(norm(name));const button=document.createElement('button');button.type='button';button.dir='auto';button.textContent=name;button.onclick=()=>{document.getElementById('shop').value=name;autoCategory(name);box.replaceChildren()};box.append(button);if(box.children.length===6)break}}
function scratchTap(key){scratchStates[key]=((scratchStates[key]||0)+1)%4;render()}const editTaps={};function salaryEditTap(key){const now=Date.now();if(!editTaps[key]||now-editTaps[key]>1800){editTaps[key]=now;return}editTaps[key]=0;confirmSmall('Открыть редактирование зарплаты?',()=>showSalaryEditor())}function testImpact(){let v=Math.max(0,Number(document.getElementById('testCost').value)||0);testValue=v;document.getElementById('impact').innerHTML=`Запас после покупки: <b class="${free()-v>=0?'green':'red'}">${fmt(free()-v)}</b><div class="small">Изменение прогноза: −${fmt(v)}</div>`}
function prettyDate(value){return new Date(value+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}
function monthName(){return new Date(d.periodEnd+'T12:00:00').toLocaleDateString('ru-RU',{month:'long'})}
function periodLabel(){return [d.periodStart,d.periodEnd].map(x=>x.split('-').reverse().join('.')).join('–')}
function numeric(key,label){return editable(key,label).replace(fmt(d[key])+'</b>',String(d[key])+'</b>')}
function dateField(key,label){return `<div class="row"><span>${label}</span><span class="field"><b class="small">${esc(d[key])}</b><button class="icon" onclick="editDate('${key}')">✎</button></span></div>`}
function editDate(key){modal(`<h3>Изменить дату</h3><input type="date" id="newDate" value="${esc(d[key])}"><div class="actions"><button onclick="closeModal()">Отмена</button><button onclick="saveDate('${key}')">Сохранить</button></div>`)}
function saveDate(key){const date=document.getElementById('newDate').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return;if(key==='periodStart'&&date>=d.periodEnd||key==='periodEnd'&&date<=d.periodStart)return;d.periodTargets[CashModel.goalKey(d)]=d.limit;d[key]=date;if(key==='periodStart'||key==='periodEnd'){d.limit=d.periodTargets[CashModel.goalKey(d)]??CashModel.strategic(d).current.balance;d.periodTargets[CashModel.goalKey(d)]=d.limit}save();closeModal();render()}
function included(key,value){d.subs.find(x=>x.id===key).included_in_statement=value;save();render()}

function setInstallment(key,field,value){d.installments.find(x=>x.id===key)[field]=value;save();render()}





function togglePeriod(key){d.selectedPeriods=d.selectedPeriods.includes(key)?d.selectedPeriods.filter(x=>x!==key):[...d.selectedPeriods,key];save();render()}
function carryExcess(){confirmSmall('Сохранить перенос для следующего периода?',()=>{d.nextPeriodCarry=CashModel.saving(d).excess;save();modal(`<h3>Перенос сохранён</h3><p>При открытии следующего периода требуемая экономия увеличится на ${fmt(d.nextPeriodCarry)}.</p><button onclick="closeModal()">Закрыть</button>`)})}
function download(name,type,contents){const url=URL.createObjectURL(new Blob([contents],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

function exportLedger(){const rows=CashModel.calculate(d).rows;const cells=v=>'"'+String(v??'').replaceAll('"','""')+'"';download('Save-Cash-reconciliation.csv','text/csv;charset=utf-8','\ufeff'+[['Статья','Сумма ₪','Источник','Инструмент','Дата операции','Дата списания','Учтена / вне периода','Статус'],...rows.map(x=>[x.name,x.amount,x.source,x.method,x.operation_date,x.date,x.included?'Да':'Нет',x.status])].map(r=>r.map(cells).join(';')).join('\r\n'))}






let swRegistration;let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});function installApp(){if(installPrompt){installPrompt.prompt();installPrompt.userChoice.then(()=>installPrompt=null);return}const ios=/iPhone|iPad|iPod/.test(navigator.userAgent)||navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1;modal(`<h3>Установить Save Cash</h3><p>${ios?'В Safari нажмите «Поделиться» → «На экран Домой» → «Добавить».':'Откройте приложение в Chrome → меню ⋮ → «Установить приложение» или «Добавить на главный экран».'}</p><p class="small">Если приложение уже установлено, запускайте значок Save Cash. Обновление не требует удаления приложения.</p><button class="compact" onclick="closeModal()">Закрыть</button>`)}


function compactSelects(root){for(const select of root.querySelectorAll('select:not([hidden])')){if(select.multiple||select.dataset.compact)continue;select.dataset.compact='true';select.hidden=true;const picker=document.createElement('details');picker.className='compact-select';const summary=document.createElement('summary');summary.textContent=select.selectedOptions[0]?.textContent||'Выбрать';const list=document.createElement('div');list.className='compact-select-options';for(const option of select.options){const button=document.createElement('button');button.type='button';button.textContent=option.textContent;button.disabled=option.disabled;button.className=option.selected?'selected':'';button.onclick=()=>{select.value=option.value;summary.textContent=option.textContent;picker.open=false;for(const b of list.children)b.classList.toggle('selected',b===button);select.dispatchEvent(new Event('change',{bubbles:true}))};list.appendChild(button)}picker.append(summary,list);select.before(picker)}queueMicrotask(()=>{if(!root.isConnected)return;for(const select of root.querySelectorAll('select[data-compact]')){const picker=select.previousElementSibling;if(picker?.classList.contains('compact-select')){picker.querySelector('summary').textContent=select.selectedOptions[0]?.textContent||'Выбрать';Array.from(picker.querySelectorAll('button')).forEach((b,i)=>b.classList.toggle('selected',select.options[i]?.selected===true))}}})}
const PURCHASE_CATEGORIES=['Продукты','Рестораны','Развлечения','Дети','Дом','Одежда','Транспорт','Аптеки','Здоровье','Ненужные покупки','Другое'];
function merchantKey(name){return String(name||'').normalize('NFKC').toLowerCase().replace(/[\s\-־–—'".]/g,'')}
function inferCategory(name){const key=merchantKey(name);if(!key)return 'Другое';const previous=[...(d.purchases||[]),...(d.planned||[])].filter(x=>!x.deleted&&merchantKey(x.name)===key&&x.category&&x.category!=='Другое').at(-1);if(previous?.category_manual)return previous.category;if(/superpharm|סופרפארם|суперфарм|bepharm|ביתמרקחת|аптек/.test(key))return 'Аптеки';if(/shufersal|שופרסל|ramilevy|רמילוי|yohananof|יוחננוף|osherad|אושרעד|victory|ויקטורי|карфур|carrefour/.test(key))return 'Продукты';if(/aroma|ארומה|арома|mcdonald|מקדונלד|кафе|ресторан/.test(key))return 'Рестораны';if(/h&m|zara|זארה|одежд/.test(key))return 'Одежда';if(/ikea|איקאה|ик(е|э)а/.test(key))return 'Дом';return previous?.category||'Другое'}
function setPurchaseCategory(value,manual=false){const select=document.getElementById('category');if(!select)return;const category=value.trim()||'Другое';if(!Array.from(select.options).some(o=>o.value===category)){const o=document.createElement('option');o.value=category;o.textContent=category;select.appendChild(o)}select.value=category;select.dataset.manual=manual?'true':'false';document.getElementById('customCategory').value='';document.getElementById('categoryChoice').textContent=category+' · изменить'}
function autoCategory(name){const select=document.getElementById('category');if(select?.dataset.manual!=='true')setPurchaseCategory(inferCategory(name))}
function categoryTap(){const selected=document.getElementById('category').value||inferCategory(document.getElementById('shop').value),choices=[...new Set([...PURCHASE_CATEGORIES,...d.dogEntries.filter(x=>!x.deleted).map(x=>'Собака / '+x.name),...(d.purchases||[]).map(x=>x.category).filter(Boolean)])];modal(`<h3>Категория покупки</h3><p class="small">Определяется по магазину. При необходимости измените.</p><div class="category-options">${choices.map((x,i)=>`<button class="compact ${x===selected?'selected':''}" data-category-choice="${i}" onclick="setPurchaseCategory(this.textContent,true);closeModal()">${esc(x)}</button>`).join('')}</div><label>Своя категория<input id="newCustomCategory" placeholder="Название категории" maxlength="80"></label><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="saveCustomCategory()">Применить</button></div>`)}
function saveCustomCategory(){const value=document.getElementById('newCustomCategory').value.trim();if(!value)return;setPurchaseCategory(value,true);closeModal()}
function saveSalary(){const n=Number(document.getElementById('newSalary').value),date=document.getElementById('newSalaryDate')?.value||d.salaryDate;if(!Number.isFinite(n)||n<0||!CashModel.validDate(date))return;d.salaryHistory.push({id:id(),at:new Date().toISOString(),oldExpected:d.salary,expected:n,oldDate:d.salaryDate,date,event:'forecast'});d.salary=n;d.salaryDate=date;Object.keys(scratchStates).forEach(k=>scratchStates[k]=0);save('Уточнение ожидаемой зарплаты');closeModal();render()}
function changeStatementStatus(){modal(`<h3>Статус выписки</h3><div class="stack">${['Частичная выписка','Полная выписка · сверена'].map(status=>`<button onclick="setStatementStatus('${status}')">${status}</button>`).join('')}<button onclick="closeModal()">Отмена</button></div><p class="small">При полной выписке отметьте входящие в неё подписки, рассрочки, Cibus и покупки.</p>`)}
function waitForUpdateWorker(reg,timeout=60000){if(reg.waiting)return Promise.resolve(reg.waiting);if(!reg.installing)return Promise.resolve(null);return new Promise((resolve,reject)=>{const worker=reg.installing,timer=setTimeout(()=>{worker.removeEventListener('statechange',change);reject(Error('Загрузка ещё не завершена. Проверьте интернет и повторите проверку.'))},timeout);function change(){if(worker.state==='installed'||reg.waiting){clearTimeout(timer);worker.removeEventListener('statechange',change);resolve(reg.waiting||worker)}else if(worker.state==='redundant'){clearTimeout(timer);worker.removeEventListener('statechange',change);reject(Error('Новая версия не загрузилась полностью. Текущая версия и данные сохранены.'))}}worker.addEventListener('statechange',change);change()})}
async function activateAppUpdate(worker){try{await Storage.flush();modal('<h3>Применяем обновление…</h3><p role="status">Данные сохранены. Ждём готовности новой версии.</p>');const controlled=new Promise((resolve,reject)=>{const timer=setTimeout(()=>{navigator.serviceWorker.removeEventListener('controllerchange',changed);reject(Error('Активация не завершилась. Закройте все окна Save Cash и откройте приложение заново. Данные очищать не нужно.'))},15000);function changed(){clearTimeout(timer);navigator.serviceWorker.removeEventListener('controllerchange',changed);resolve()}navigator.serviceWorker.addEventListener('controllerchange',changed,{once:true})});worker.postMessage('ACTIVATE_UPDATE');await controlled;window.location.reload()}catch(e){showError('Обновление не завершено',e.message)}}
async function checkUpdate(){try{if(!swRegistration){modal('<h3>Обновление пока недоступно</h3><p>Откройте приложение по HTTPS и дождитесь готовности офлайн-режима.</p><button onclick="closeModal()">Закрыть</button>');return}modal('<h3>Проверяем обновление…</h3><p role="status">Загружаем новую версию. Данные остаются на устройстве.</p>');await swRegistration.update();const worker=await waitForUpdateWorker(swRegistration);if(worker)confirmSmall('Новая версия готова. Сохранить данные и обновить приложение?',()=>activateAppUpdate(worker));else modal('<h3>Установлена актуальная версия</h3><p>Save Cash RC6.1. Если на главной странице нет прогноза после аренды, закройте все окна приложения и откройте его снова. Данные сайта не очищайте.</p><button onclick="closeModal()">Закрыть</button>')}catch(e){showError('Не удалось проверить обновление',e.message)}}

