function legacyEditPurchase(key){const x=d.purchases.find(x=>x.id===key);modal(`<h3>Покупка</h3><div class="form-row"><label>Название</label><input id="editName" value="${esc(x.name)}"></div><div class="form-row"><label>Сумма</label><input id="editAmount" type="number" value="${x.amount}" step=".01" min="0"></div><div class="form-row"><label>Дата покупки</label><input id="editDate" type="date" value="${esc(x.date)}"></div><div class="form-row"><label>Дата списания</label><input id="editCharge" type="date" value="${esc(CashModel.chargeDate(x,d))}"></div><div class="form-row"><label>Статус</label>${statusPicker('editStatus',x.status,false)}</div><div class="form-row"><label>Связь с рассрочкой, подпиской или уроками</label><select id="editLink"><option value="">Нет</option>${d.installments.map(i=>`<option value="${i.id}" ${x.installment_id===i.id?'selected':''}>${esc(i.merchant)}</option>`).join('')}${d.subs.map(i=>`<option value="${i.id}" ${x.recurring_id===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}${CashModel.lessonPayments(d).map(p=>`<option value="lesson:${p.id}" ${x.lesson_payment_id===p.id?'selected':''}>${esc(p.name)} · ${esc(p.charge_date)} · ${fmt(p.amount)}</option>`).join('')}</select></div><div class="actions"><button onclick="closeModal()">Отмена</button><button onclick="savePurchase('${key}')">Сохранить</button></div>`)}
function legacySavePurchase(key){const x=d.purchases.find(x=>x.id===key),amount=Number(document.getElementById('editAmount').value);if(!Number.isFinite(amount)||amount<=0)return;Object.assign(x,{name:document.getElementById('editName').value.trim()||x.name,amount,date:document.getElementById('editDate').value,charge_date:document.getElementById('editCharge').value,status:document.getElementById('editStatus').value,installment_id:document.getElementById('editLink').value.startsWith('sub-')?'':document.getElementById('editLink').value,recurring_id:document.getElementById('editLink').value.startsWith('sub-')?document.getElementById('editLink').value:''});if(document.getElementById('editLink').value.startsWith('lesson:')){x.lesson_payment_id=document.getElementById('editLink').value.slice(7);x.installment_id='';x.recurring_id=''}else delete x.lesson_payment_id;x.included_in_statement=CashModel.method(x.method)==='credit'&&['Включено в выписку','Списано со счёта'].includes(x.status);save();closeModal();render()}

