function statusPicker(key,current){const values=['Совершено','Запланировано'],selected=values.includes(current)?current:'Совершено';return `<select id="${key}" aria-label="Статус покупки">${values.map(v=>`<option ${v===selected?'selected':''}>${v}</option>`).join('')}</select>`}
