function addLessonPayment(){syncLessonDraft();lessonDraft.payments.push({id:id(),amount:Math.max(0,lessonDraft.total-sum(lessonDraft.payments)),charge_date:d.statementDate,method:'Ашрай',included_in_statement:false});lessonEditor()}
function removeLessonPayment(i){syncLessonDraft();lessonDraft.payments.splice(i,1);lessonEditor()}


async function importLessonUpdate(raw){if(raw.app!=='Save Cash'||raw.version!==1)throw Error('Неизвестный формат обновления');validateLessons(raw.lessonBills);const bills=structuredClone(d.lessonBills);for(const b of raw.lessonBills){const i=bills.findIndex(x=>x.id===b.id);if(i>=0)bills[i]=b;else bills.push(b)}validateLessons(bills);confirmSmall('Добавить счета за уроки? Покупки, баланс и остальные данные сохранятся.',async()=>{await Storage.flush();await Storage.backup('before-lesson-update',d);d.lessonBills=bills;if(typeof raw.childName==='string')d.childName=raw.childName;if(typeof raw.lessonRecipient==='string')d.lessonRecipient=raw.lessonRecipient.slice(0,80);save();closeModal();render()})}
function calculationRows(){if(!Array.isArray(d.calculations)||!d.calculations.length)d.calculations=[{id:id(),terms:[0]}];return d.calculations}
function calcTotal(){return calculationRows().reduce((s,r)=>s+r.terms.reduce((a,n)=>a+CashModel.cents(n),0),0)/100}
function calculatorHTML(){const total=calcTotal();return `<div class="calculator"><h3>Проверка покупки + калькулятор</h3><div class="small">Нажмите на число: откроется цифровая панель. «＋» добавляет слагаемое или ещё один расчёт.</div>${calculationRows().map((r,i)=>`<div class="calc-row"><div class="calc-expression">${r.terms.map((n,j)=>`${j?'<span class="small">+</span>':''}<button class="calc-number" onclick="openKeypad(${i},${j})" aria-label="Расчёт ${i+1}, число ${j+1}">${fmt(n).replace(' ₪','')}</button>`).join('')}<button class="calc-add" onclick="appendTerm(${i})" aria-label="Добавить число в расчёт ${i+1}">＋</button></div><div class="calc-result"><span>= ${fmt(r.terms.reduce((a,n)=>a+CashModel.cents(n),0)/100)}</span>${calculationRows().length>1?`<button onclick="removeCalculation(${i})">Убрать</button>`:''}</div></div>`).join('')}<button class="compact calc-plus" onclick="addCalculation()">＋ Ещё расчёт</button><div class="gray calc-impact">Итого проверяем: <b>${fmt(total)}</b><br>Запас после покупки: <strong class="${free()-total>=0?'green':'red'}">${fmt(free()-total)}</strong></div><div class="small">Это примерка расходов. В журнал покупки не записываются.</div></div>`}
function addCalculation(){calculationRows().push({id:id(),terms:[0]});save();render()}
function removeCalculation(i){calculationRows().splice(i,1);save();render()}
function appendTerm(i){calculationRows()[i].terms.push(0);openKeypad(i,calculationRows()[i].terms.length-1)}
let keypadState;
function openKeypad(row,index){keypadState={row,index,value:String(calculationRows()[row].terms[index]||0)};modal(`<h3>Число для расчёта</h3><div id="keypadValue" class="keypad-value">${esc(keypadState.value.replace('.',','))}</div><div class="keypad">${['7','8','9','⌫','4','5','6','C','1','2','3','+','0',',','00','✓'].map(v=>`<button class="${v==='✓'?'primary':''}" onclick="keypadPress('${v}')" aria-label="${v==='⌫'?'Удалить цифру':v==='✓'?'Записать число':v==='C'?'Очистить число':v}">${v}</button>`).join('')}</div><div class="keypad-actions"><button class="compact" onclick="closeModal();render()">Отмена</button><button class="compact" onclick="keypadPress('✓')">Записать</button></div>`)}
function keypadPress(key){const k=keypadState;if(key==='✓'||key==='+'){const n=Number(k.value);if(!Number.isFinite(n)||n<0)return;calculationRows()[k.row].terms[k.index]=n;save();if(key==='+'){calculationRows()[k.row].terms.push(0);openKeypad(k.row,calculationRows()[k.row].terms.length-1)}else{closeModal();render()}return}if(key==='C')k.value='0';else if(key==='⌫')k.value=k.value.slice(0,-1)||'0';else if(key===','){if(!k.value.includes('.'))k.value+='.'}else if(k.value.length<12&&(!k.value.includes('.')||k.value.split('.')[1].length<2)){const next=k.value==='0'?key:k.value+key;if(!next.includes('.')||next.split('.')[1].length<=2)k.value=next}document.getElementById('keypadValue').textContent=k.value.replace('.',',')}




let receiptDraft=null,ocrBusy=false,bankDraft=null,bankRunId=null,reconFocusId=null,ledgerSort={key:'name',asc:true},ledgerQuery='';
function save(action='Изменение данных'){if(typeof CashArchive!=='undefined')CashArchive.capture(d,action);d.schemaVersion=2;d.dataVersion=5;BudgetFeatures.ensure(d);d.financialRevision=(d.financialRevision||0)+1;d.audit_log.push({id:id(),at:new Date().toISOString(),action});return Storage.save(d).catch(storageError)}
function validData(raw){return CashValidation.data(raw)}
function validateLessons(bills){return CashValidation.lessons(bills)}
async function start(){document.getElementById('app').innerHTML='<section class="card">Открываем ваши данные…</section>';try{const raw=await Storage.load();if(raw.dataVersion!==5)await Storage.backup('before-2026-10-16-migration',raw);d=CashModel.migrate(raw);if(typeof CashArchive!=='undefined')CashArchive.initialize(d);if(typeof CashCalendar!=='undefined')CashCalendar.sync(d,new Date(),CashModel.calculate(d));await Storage.migrateAttachments(d);if(typeof CashArchive!=='undefined')CashArchive.capture(d,'Обновление расчётного календаря при запуске');await Storage.save(d);ready=true;render();if(typeof packageReady==='function')packageReady()}catch(e){document.getElementById('app').innerHTML='<section class="card">Не удалось открыть хранилище. Данные не перезаписаны. '+esc(e.message)+'</section>'}}
function showSettings(){modal(`<div class="settings-head"><div><h3>Save Cash <span class="pill">v3.0 RC7</span></h3><div class="small">Бюджет до ЗП · 19.10.2026</div></div><button class="close-button" onclick="closeModal()" aria-label="Закрыть настройки">×</button></div><div class="settings-status"><span class="status-dot"></span>${swRegistration?.active?'Локальное хранилище и офлайн-режим готовы':'Подготавливаем офлайн-режим'}</div><div class="settings-group"><button class="settings-row" onclick="installApp()">${uiIcon('phone')}<span>Установить приложение</span><span>›</span></button><button class="settings-row" onclick="checkUpdate()">${uiIcon('refresh')}<span>Проверить обновление</span><span>›</span></button></div><div class="settings-group"><button class="settings-row" onclick="showAccountArchive()"><span>Выписка по счетам<small>История, фильтры и отчёты</small></span><span>›</span></button></div><div class="settings-label">Данные</div><div class="settings-group"><button class="settings-row" onclick="exportBackup()">${uiIcon('export')}<span>Полная резервная копия<small>ZIP: данные, оригиналы и журнал</small></span><span>›</span></button><button class="settings-row" onclick="exportData()">${uiIcon('export')}<span>Экспорт JSON<small>Данные без файлов документов</small></span><span>›</span></button><button class="settings-row" onclick="document.getElementById('restoreFile').click()">${uiIcon('folder')}<span>Восстановить ZIP / JSON</span><span>›</span></button><input id="restoreFile" type="file" accept=".zip,.json" hidden onchange="importData(this.files[0])"><button class="settings-row" onclick="showPeriodSettings()">${uiIcon('calendar')}<span>Расчётный период и даты</span><span>›</span></button><button class="settings-row" onclick="showBalanceHistory()">${uiIcon('refresh')}<span>История баланса</span><span>›</span></button><button class="settings-row" onclick="showSingleCardHistory()">${uiIcon('folder')}<span>Разовые операции · история</span><span>›</span></button><button class="settings-row" onclick="showDeleted()">${uiIcon('folder')}<span>Удалённые записи</span><span>›</span></button><button class="settings-row" onclick="showAccessInfo()">${uiIcon('sliders')}<span>Доступ и защита</span><span>›</span></button></div><div class="settings-rights">Save Cash — Бюджет до ЗП<br>© 2026 Anton Koval. All rights reserved.<br>Personal finance management application.</div><p class="small">OCR работает на устройстве. Для первой загрузки движка нужен интернет; документы не отправляются сервисам распознавания.</p>`)}
function showAccessInfo(){modal('<h3>Доступ и защита</h3><p>Финансовые данные и документы находятся только в IndexedDB этого устройства. Публичный сайт не содержит ваших сумм.</p><p>На GitHub Pages серверная авторизация новых устройств и двухчасовые приглашения недоступны. Сервер управления доступом пока не подключён. Этот выпуск не выдаёт локальное скрытие интерфейса за защиту доступа.</p><button class="compact" onclick="closeModal()">Закрыть</button>')}
function editBankBalance(){const keys=['loan','rent','statement','alimony',...Object.keys(d.paymentStates).filter(k=>k.includes('|')||k.startsWith('rent:'))].filter(k=>d.paymentStates[k]?.bank_state==='pending'||d.paymentStates[k]?.balance_reflected===false);modal(`<h3>Изменить баланс банка</h3><label>Сумма, ₪<input id="bankBalance" type="number" step=".01" value="${d.balance}"></label><label>Баланс актуален на дату<input id="bankBalanceDate" type="date" value="${esc(d.balanceDate)}"></label><p class="small">Это подтверждённый снимок банка, не доход. Отметьте только реально вошедшие в него списания и укажите их фактические даты.</p>${keys.map(k=>`<label class="small"><input type="checkbox" data-balance-settled="${k}" onchange="document.getElementById('settled-${k}').hidden=!this.checked"> Новый баланс включает ${{loan:'кредит',rent:'аренду',statement:'credit',alimony:'алименты'}[k]||(k.startsWith('rent:')?'аренду · '+esc(k.slice(5)):'credit карты · '+esc(k))}</label><label class="small" id="settled-${k}" hidden>Фактическая дата<input type="date" data-settled-date="${k}" value="${esc(d.paymentStates[k]?.actual_debit_date||'')}"></label>`).join('')}${d.fixedPayments.filter(x=>!x.deleted&&x.balance_reflected===false).map(x=>`<label class="small"><input type="checkbox" data-balance-fixed="${x.id}"> Новый баланс включает ${esc(x.name)} · ${fmt(x.amount)}${x.actual_debit_date?' · '+esc(x.actual_debit_date):' — подтвердите фактическую дату в редакторе статьи'}</label>`).join('')}<div id="balanceError" class="red small"></div><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="saveBankBalance()">Сохранить</button></div>`)}
function saveBankBalance(){try{const value=document.getElementById('bankBalance').value,date=document.getElementById('bankBalanceDate').value;if(value==='')throw Error('Укажите сумму баланса');const settled=Array.from(document.querySelectorAll('[data-balance-settled]:checked')).map(x=>({key:x.dataset.balanceSettled,date:document.querySelector(`[data-settled-date="${x.dataset.balanceSettled}"]`).value})),fixed=Array.from(document.querySelectorAll('[data-balance-fixed]:checked')).map(x=>d.fixedPayments.find(p=>p.id===x.dataset.balanceFixed));for(const entry of settled)if(!CashModel.validDate(entry.date)||entry.date>date)throw Error('Укажите фактическую дату списания '+entry.key+' не позже даты баланса');for(const entry of fixed)if(!CashModel.validDate(entry.actual_debit_date)||entry.actual_debit_date>date)throw Error('Сначала подтвердите дату списания '+entry.name+' в редакторе статьи');CashModel.adjustBalance(d,Number(value),date);for(const x of settled)d.paymentStates[x.key]={...d.paymentStates[x.key],balance_reflected:true,bank_state:'debited',actual_debit_date:x.date};for(const x of fixed){x.balance_reflected=true;x.bank_state='debited'}save('Корректировка банковского баланса');closeModal();render()}catch(e){document.getElementById('balanceError').textContent=e.message}}

function showBalanceHistory(){modal(`<h3>История баланса</h3>${d.balanceHistory.slice().reverse().map(x=>`<div class="purchase small">${esc(x.at)}<br>${fmt(x.old)} → <b>${fmt(x.new)}</b><br>Баланс на ${esc(x.balanceDate)}</div>`).join('')||'<p class="small">Корректировок ещё нет.</p>'}<button class="compact" onclick="closeModal()">Закрыть</button>`)}
function editMoneyKey(key,label){if(key==='limit')return editTarget();modal(`<h3>${esc(label)}</h3><div class="form-row"><label>Сумма, ₪</label><input id="keyMoney" type="number" step=".01" value="${Number(d[key])||0}"></div><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="saveMoneyKey('${key}')">Сохранить</button></div>`)}
function saveMoneyKey(key){const n=Number(document.getElementById('keyMoney').value);if(!Number.isFinite(n)||!['balance','limit'].includes(key)&&n<0)return;d[key]=n;if(key==='educationFee')d.math=n;save();closeModal();render()}
function debtScaleHTML(){const s=CashModel.scenario(d,extraSpending),bank=CashModel.bankSnapshot(d,new Date()),axis=CashModel.scaleAxis(bank.confirmed,s.forecast,d.limit),pct=axis.position,day=Number(TODAY().slice(-2)),p=CashModel.strategic(d);return `<div class="debt-scale"><div class="small">Подтверждённый баланс ${fmt(bank.confirmed)} · после обязательств <b class="scenario-forecast">${fmt(s.forecast)}</b></div><div class="scale-endpoints"><span>+${fmt(axis.positive)}</span><span>Долг →</span></div><div class="debt-track live-debt-track" style="background:linear-gradient(to right,#30a56c 0 ${pct(0)}%,#f4da67 ${pct(0)}% ${pct(-2000)}%,#ff9b36 ${pct(-2000)}% ${pct(-4000)}%,#e87373 ${pct(-4000)}% 100%)"><span class="today-pin forecast-triangle" style="left:${pct(s.forecast)}%" title="Прогноз после обязательств ${fmt(s.forecast)}"><b>${day}</b><i>▼</i></span><span class="current-bank-pin" style="left:${pct(bank.confirmed)}%" title="Подтверждённый баланс ${fmt(bank.confirmed)}"><i aria-hidden="true"></i></span><span class="target-pin" style="left:${pct(d.limit)}%" title="Цель ${fmt(d.limit)}"></span></div><div class="debt-labels"><span style="left:${pct(0)}%">0</span><span style="left:${pct(-2000)}%">−2 000</span><span style="left:${pct(-4000)}%">−4 000</span><span style="left:${pct(-6000)}%">−6 000 ₪</span></div><div class="small scale-explanation">▼ ${day} — прогноз после обязательств · сплошная засечка с ромбом — подтверждённый баланс · пунктир — цель</div><div class="scale-distance ${s.forecast>=0?'green':'red'}">${s.forecast>=0?'Прогнозируемый запас до нуля: '+fmt(s.forecast):'Прогнозируемый запас до нуля: '+fmt(0)+' · не хватает '+fmt(-s.forecast)}</div><div class="small red scenario-debt-warning">${s.forecast < -6000?'Превышение предела −6 000 ₪: '+fmt(-6000-s.forecast):''}</div><details class="strategy"><summary>План выхода из минуса · 15.01.2027</summary>${p.checkpoints.map(x=>item(x.date,x.balance)).join('')}<div class="small">Разница ручной цели и плана: ${fmt(p.manualDifference)}. Прошлые контрольные точки не меняются.</div></details></div>`}

function childHTML(){const off=CashModel.compensation(d),bills=d.lessonBills.filter(b=>b.subject==='hebrew'&&!b.deleted);return `<div class="gray"><h3>Алименты</h3>${editable('childSupport','Базовые алименты')}${editable('educationFee','Образование · в переводе')}${dateField('childDate','Дата перевода')}${item('Всего начислено',Number(d.childSupport)+CashModel.education(d))}</div>${lessonAccountHTML('math')}${lessonAccountHTML('hebrew')}<div class="gray"><h3>Компенсационный вычет</h3>${bills.filter(b=>CashModel.inPeriod(d,b.compensation_date)).map(b=>{const s=CashModel.lessonShares(b.total,b.shares_override);return `<div class="row"><span>${esc(b.name)}<div class="small">(доля мамы ${fmt(s.mother)}, моя ${fmt(s.father)})<br>Вычет один раз · ${esc(b.compensation_date)}</div></span><span class="small">Дата вычета: ${esc(b.compensation_date)}</span></div>`}).join('')}${!bills.length&&off?'<p class="small">Сохранён прежний вычет до заполнения счёта за уроки. Добавьте счёт для автоматического расчёта.</p>':''}${item('Однократный вычет из алиментов',-off,'green')}${CashModel.compensationEvents(d).map(x=>'<p class="small">'+esc(x.date)+' · '+fmt(x.amount)+' · только в этом периоде</p>').join('')}<p class="small">Доля мамы уменьшает перевод. Отдельный приход денег не начисляется.</p></div><div class="gray"><div class="row"><h3>Дополнительные расходы</h3><button class="compact" onclick="addItem('extra')">＋</button></div>${d.extra.filter(x=>!x.deleted).map(x=>editableItem('extra',x)).join('')}${item('Дополнительно',sum(d.extra.filter(x=>!x.deleted)))}</div><div class="gray"><p class="small">Перевод = база + образование + дополнительные расходы − однократная компенсация. Математика 200 ₪ — требует подтверждения знака и взаимозачёта; сумма не добавляется автоматически; уточните назначение через карандаш соответствующей статьи.</p>${item('К перечислению',CashModel.alimony(d),'green')}${item('Оплаты преподавателям в периоде',sum(CashModel.calculate(d).rows.filter(p=>p.kind==='lesson'&&!p.included)))}${item('Предстоящая нагрузка',child(),'green')}<p class="small">Уже проведённые списания и суммы внутри credit отдельно не вычитаются.</p></div>`}
function lessonAccountHTML(subject){const title=(subject==='hebrew'?'Иврит':'Математика')+' '+(d.lessonRecipient||d.childName||'ребёнку');return `<div class="gray"><div class="row"><h3>${esc(title)}</h3><button class="compact" onclick="editLesson('','${subject}')" aria-label="Добавить счёт: ${esc(title)}">＋</button></div><div class="small">${subject==='hebrew'?'Доля мамы: половина счёта вниз до сотни, затем минус 100 ₪. Моя доля — остаток.':'Личные расходы; суммы, передаваемые маме, входят в образование алиментов.'}</div>${d.lessonBills.filter(b=>b.subject===subject&&!b.deleted).map(b=>{const s=CashModel.lessonShares(b.total,b.shares_override),paid=sum(b.payments.filter(p=>p.paid));return `<div class="lesson-bill"><div class="row"><span>${esc(b.name)}<div class="small">${b.lessons||0} уроков${b.via_alimony?' · в переводе алиментов':''}</div></span><span class="field"><b class="money">${fmt(b.total)}</b><button class="icon" onclick="editLesson('${b.id}','${subject}')" aria-label="Изменить счёт ${esc(b.name)}">✎</button></span></div>${subject==='hebrew'?`<div class="small">(доля мамы ${fmt(s.mother)}, моя ${fmt(s.father)})${s.manual?' · подтверждено вручную':''}</div>`:''}<div class="small">Оплачено ${fmt(paid)} · осталось ${fmt(b.total-paid)}</div>${b.payments.map(p=>`<div class="lesson-payment"><span>Списание ${esc(p.charge_date||'дата не подтверждена')} · ${methodLabel(p.method)}<br>${p.operation_date?'Операция '+esc(p.operation_date):'Дата операции требует уточнения'}<br>${p.charge_date<=d.balanceDate?'Уже в исходном балансе':p.included_in_statement?'В общей выписке':'Отдельный платёж / прогноз'}</span><strong>${fmt(p.amount)}</strong></div>`).join('')}</div>`}).join('')||'<div class="empty">Добавьте счёт за уроки</div>'}</div>`}
function editLesson(key,subject){lessonDraft=structuredClone(d.lessonBills.find(b=>b.id===key)||{id:id(),subject,name:'Счёт за уроки',total:0,lessons:0,compensation_date:d.childDate,via_alimony:false,payments:[{id:id(),amount:0,charge_date:d.statementDate,operation_date:'',payment_date:'',method:'credit',paid:false,included_in_statement:false}]});lessonEditor()}
function lessonEditor(){const b=lessonDraft;modal(`<h3>${b.subject==='hebrew'?'Иврит':'Математика'} · счёт</h3><div class="two"><div class="form-row"><label>Название</label><input id="lessonName" value="${esc(b.name)}"></div><div class="form-row"><label>Уроков</label><input id="lessonCount" type="number" min="0" value="${b.lessons||0}"></div></div><div class="form-row"><label>Весь счёт, ₪</label><input id="lessonTotal" type="number" min="0" step=".01" value="${b.total}" oninput="previewShares()"></div><div id="lessonShares" class="small"></div>${b.subject==='hebrew'?`<div class="form-row"><label>Дата однократного вычета</label><input id="lessonOffsetDate" type="date" value="${esc(b.compensation_date)}"></div><details class="help" ${b.shares_override?'open':''}><summary>Исключение для этого счёта</summary><div class="form-row"><label>Доля мамы, ₪</label><input id="motherOverride" type="number" min="0" step=".01" value="${b.shares_override?.mother??''}"></div><label><input id="confirmShares" type="checkbox" ${b.shares_override?.confirmed?'checked':''}> Подтверждаю ручные доли</label><p>Без подтверждения применяется автоматическая формула.</p></details>`:`<label class="small"><input id="lessonViaAlimony" type="checkbox" ${b.via_alimony?'checked':''}> Передаю эту сумму маме в составе образования</label>`}<h3 style="font-size:14px;margin-top:15px">Платежи</h3>${b.payments.map((p,i)=>`<div class="lesson-editor"><div class="two"><div class="form-row"><label>Сумма, ₪</label><input id="lpAmount${i}" type="number" min="0" step=".01" value="${p.amount}"></div><div class="form-row"><label>Дата банковского списания</label><input id="lpDate${i}" type="date" value="${esc(p.charge_date)}"></div><div class="form-row"><label>Дата операции</label><input id="lpOperation${i}" type="date" value="${esc(p.operation_date||'')}"></div><div class="form-row"><label>Дата оплаты</label><input id="lpPaidDate${i}" type="date" value="${esc(p.payment_date||'')}"></div></div><div class="row"><select id="lpMethod${i}">${['credit','Paybox credit','debit','cash'].map(m=>`<option value="${m}" ${p.method===m||m!=='Paybox credit'&&p.method!=='Paybox credit'&&CashModel.method(p.method)===m?'selected':''}>${m==='cash'?'Наличные':m==='Paybox credit'?'Paybox с кредитной карты':m}</option>`).join('')}</select><label class="small"><input id="lpPaid${i}" type="checkbox" ${p.paid?'checked':''}> Уже оплатил</label></div><label class="small"><input id="lpIncluded${i}" type="checkbox" ${p.included_in_statement?'checked':''}> В общей выписке credit</label>${b.payments.length>1?`<button class="payment-remove" onclick="removeLessonPayment(${i})">Убрать платёж</button>`:''}</div>`).join('')}<button class="compact" onclick="addLessonPayment()">＋ Ещё платёж</button><p class="small">Сумма оплат должна совпадать со счётом. Неизвестную фактическую дату оставьте пустой.</p><div id="lessonError" class="small red"></div><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="saveLesson()">Сохранить</button></div>`);previewShares()}
function previewShares(){const total=Number(document.getElementById('lessonTotal').value),s=CashModel.lessonShares(total);document.getElementById('lessonShares').textContent=lessonDraft.subject==='hebrew'?'Доля мамы '+fmt(s.mother)+' · моя '+fmt(s.father):'Личные расходы '+fmt(total)}
function syncLessonDraft(){Object.assign(lessonDraft,{name:document.getElementById('lessonName').value.trim()||'Счёт за уроки',total:Number(document.getElementById('lessonTotal').value),lessons:Number(document.getElementById('lessonCount').value)||0,compensation_date:document.getElementById('lessonOffsetDate')?.value||lessonDraft.compensation_date,via_alimony:document.getElementById('lessonViaAlimony')?.checked||false});const mother=document.getElementById('motherOverride'),confirmed=document.getElementById('confirmShares');lessonDraft.shares_override=confirmed?.checked?{mother:Number(mother.value),confirmed:true,at:new Date().toISOString()}:null;lessonDraft.payments.forEach((p,i)=>Object.assign(p,{amount:Number(document.getElementById('lpAmount'+i).value),charge_date:document.getElementById('lpDate'+i).value,operation_date:document.getElementById('lpOperation'+i).value,payment_date:document.getElementById('lpPaidDate'+i).value,method:document.getElementById('lpMethod'+i).value,paid:document.getElementById('lpPaid'+i).checked,included_in_statement:document.getElementById('lpIncluded'+i).checked}))}
function saveLesson(){syncLessonDraft();try{const previous=d.lessonBills.find(b=>b.id===lessonDraft.id),bills=d.lessonBills.filter(b=>b.id!==lessonDraft.id).concat(lessonDraft);validateLessons(bills);const delta=(lessonDraft.via_alimony?lessonDraft.total:0)-(previous?.via_alimony?previous.total:0);d.educationFee=Math.max(0,d.educationFee+delta);d.math=d.educationFee;d.lessonBills=bills;save('Счёт за уроки');closeModal();render()}catch(e){document.getElementById('lessonError').textContent=e.message}}
function methodLabel(value){return {credit:'credit',debit:'debit',cash:'Наличные',unconfirmed:'Не подтверждён'}[CashModel.method(value)]||value}
function removeItem(collection,key){confirmSmall('Удалить эту статью?',()=>{CashModel.removeRecord(d,{collection,id:key});save('Удаление с сохранением истории');closeModal();render()})}
function showDeleted(){modal(`<h3>Удалённые записи</h3>${d.deletedRecords.filter(x=>!x.restoredAt).map(x=>`<div class="row"><span class="small">${esc(x.record?.name||x.record?.merchant||x.ref.row_id)}<br>${esc(x.at)}</span><button class="compact" onclick="restoreDeleted('${x.id}')">Восстановить</button></div>`).join('')||'<p class="small">Нет удалённых записей.</p>'}<button class="compact" onclick="closeModal()">Закрыть</button>`)}
function restoreDeleted(key){CashModel.restoreRecord(d,key);save('Восстановление записи');closeModal();render()}
let receiptJob=0;
function registerDocument(meta){d.documents=d.documents||[];if(!d.documents.some(x=>x.id===meta.id))d.documents.push(meta)}
function receiptDraftHTML(){if(!receiptDraft)return '';const r=receiptDraft.ocr;return `<div class="gray receipt-review"><div class="row"><b>Товары в чеке</b><span><button class="compact" onclick="cancelOCRDraft()">Отмена</button>${r?`<button class="compact" onclick="toggleReceiptTranslation()">${r.show_translation?'Оригинал':'Перевести'}</button>`:''}<button class="photo-button" onclick="openDocument('${receiptDraft.document_id}')" aria-label="Оригинал чека">${uiIcon('gallery')}</button></span></div>${receiptDraft.error?`<div class="small red">${esc(receiptDraft.error)}</div><button class="compact" onclick="retryReceipt()">Повторить OCR</button><label class="small"><input id="receiptManualConfirmed" type="checkbox"> Проверю и введу данные вручную</label>`:`<div class="small">OCR на устройстве · HE / EN / RU. ${r.derived_total?'Итог предложен по совпадению оплаты и суммы товаров; проверьте итоговую строку.':''}</div><div class="ocr-checks">${Object.entries(r.fields).map(([k,v])=>`<div class="small">${{name:'Магазин',date:'Дата',amount:'Итог'}[k]}: ${v.confidence===null||v.confidence===undefined?'уверенность не определена':Math.round(v.confidence)+'% по распознанному полю'}${v.review?`<label><input data-ocr-review="${k}" type="checkbox" ${receiptReviewValid()?'checked':''} onchange="recordReceiptReview()"> Проверено по оригиналу</label>`:''}</div>`).join('')}</div>${receiptItemsHTML(r.items,r.translations,r.show_translation,true)}${r.adjustments.map((x,i)=>`<div class="receipt-item small"><span dir="auto">${esc(x.name)}</span><span>${fmt(x.amount)} <button class="icon" onclick="editReceiptItem(${i},true)">✎</button></span></div>`).join('')}<button class="compact" onclick="editReceiptItem(-1,false)">＋ Товар</button><div class="small">Сумма строк: ${fmt(r.items.reduce((s,x)=>s+x.amount,0)+r.adjustments.reduce((s,x)=>s+x.amount,0))}</div><div class="small red">${Math.abs(r.items.reduce((s,x)=>s+x.amount,0)+r.adjustments.reduce((s,x)=>s+x.amount,0)-Number(document.getElementById('amount')?.value||r.total))>.02?'Сумма товаров отличается от итога: проверьте скидки, количества и НДС':''}</div><label class="small"><input id="receiptItemsConfirmed" type="checkbox" ${receiptReviewValid()?'checked':''} onchange="recordReceiptReview()"> Проверены товары, количества, скидки и расхождение с итогом</label><details class="small"><summary>Исходный распознанный текст</summary><pre dir="auto" style="white-space:pre-wrap">${esc(r.text)}</pre></details>`}</div>`}
function receiptReviewToken(){if(!receiptDraft?.ocr)return '';return JSON.stringify({name:document.getElementById('shop')?.value,amount:document.getElementById('amount')?.value,date:document.getElementById('date')?.value,items:receiptDraft.ocr.items,adjustments:receiptDraft.ocr.adjustments})}
function receiptReviewValid(){return !!receiptDraft?.ocr?.reviewedToken&&receiptDraft.ocr.reviewedToken===receiptReviewToken()}
function recordReceiptReview(){if(receiptDraft?.ocr&&Array.from(document.querySelectorAll('[data-ocr-review]')).every(x=>x.checked)&&document.getElementById('receiptItemsConfirmed')?.checked)receiptDraft.ocr.reviewedToken=receiptReviewToken();else if(receiptDraft?.ocr)delete receiptDraft.ocr.reviewedToken}
function receiptCriticalErrors(){const errors=[];if(!document.getElementById('shop').value.trim())errors.push('Название магазина');if(!(Number(document.getElementById('amount').value)>0))errors.push('Итоговая сумма');if(!CashModel.validDate(document.getElementById('date').value))errors.push('Дата покупки');for(const [i,x]of (receiptDraft?.ocr?.items||[]).entries())if(!x.name?.trim()||!Number.isFinite(x.amount))errors.push('Товар '+(i+1)+': название или сумма');return errors}
function showOCRReview(){const errors=receiptCriticalErrors();modal(`<h3>Проверьте поля OCR и товары</h3><p class="small">Подтвердите, что вы сверили магазин, дату, итог, товары и скидки с оригиналом. Покупка пока не сохраняется.</p>${errors.length?`<p class="small red">Исправьте: ${errors.map(esc).join(', ')}</p>`:''}<div id="ocrReviewError" class="small red"></div><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="confirmOCRReview()">Подтвердить</button></div>`)}
function confirmOCRReview(){const errors=receiptCriticalErrors();if(errors.length){document.getElementById('ocrReviewError').textContent='Исправьте: '+errors.join(', ');return}const r=receiptDraft.ocr;for(const item of r.items){item.user_confirmed=true;item.review=false}r.reviewedToken=receiptReviewToken();r.corrected={name:document.getElementById('shop').value.trim(),amount:Number(document.getElementById('amount').value),date:document.getElementById('date').value,items:structuredClone(r.items),adjustments:structuredClone(r.adjustments),confirmedAt:new Date().toISOString()};save('Подтверждено OCR — только черновик');closeModal();updateReceiptView()}
function updateReceiptView(){document.getElementById('ocrDraftContainer').innerHTML=receiptDraftHTML()}
async function attachReceipt(file){if(!file)return;if(!/^image\/(jpeg|png|webp|gif|bmp|heic|heif)$/.test(file.type)){modal('<h3>Выберите фотографию JPEG, PNG, WebP или HEIC</h3><button onclick="closeModal()">Закрыть</button>');return}const job=++receiptJob;ocrBusy=true;document.getElementById('receiptNotice').textContent='Сохраняем оригинал и запускаем OCR на устройстве…';try{const meta=await Storage.storeDocument(file,'receipt');registerDocument(meta);const data=await DocumentEngine.recognize(file,p=>{if(job===receiptJob)document.getElementById('receiptNotice').textContent='OCR: '+p.status+' '+Math.round((p.progress||0)*100)+'%'});if(job!==receiptJob)return;const ocr=DocumentEngine.receipt(data.text,data.confidence,data);receiptDraft={document_id:meta.id,ocr};if(ocr.fields.name.value){document.getElementById('shop').value=ocr.fields.name.value;autoCategory(ocr.fields.name.value);}if(ocr.fields.date.value)document.getElementById('date').value=ocr.fields.date.value;if(ocr.fields.amount.value!==null)document.getElementById('amount').value=ocr.fields.amount.value;document.getElementById('receiptNotice').textContent='Распознано на устройстве. Проверьте отмеченные поля и товары.';save('Распознан чек — черновик');updateReceiptView()}catch(e){if(job===receiptJob){receiptDraft={document_id:d.documents?.at(-1)?.id||'',error:'OCR не выполнен: '+e.message};document.getElementById('receiptNotice').textContent='Распознавание не завершено.';updateReceiptView()}}finally{if(job===receiptJob)ocrBusy=false}}
async function retryReceipt(){const doc=await Storage.getDocument(receiptDraft.document_id);if(doc){doc.blob.name=doc.name;await attachReceipt(doc.blob)}}
function editReceiptItem(index,adjustment){const x=(adjustment?receiptDraft.ocr.adjustments:receiptDraft.ocr.items)[index]||{name:'',amount:0};modal(`<h3>${adjustment?'Скидка / корректировка':'Товар'}</h3><div class="form-row"><label>Название</label><input id="receiptItemName" dir="auto" value="${esc(x.name)}"></div><div class="form-row"><label>Сумма, ₪</label><input id="receiptItemAmount" type="number" step=".01" value="${x.amount}"></div><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button>${index>=0?`<button class="compact danger" onclick="removeReceiptItem(${index},${adjustment})">Удалить</button>`:''}<button class="compact primary" onclick="saveReceiptItem(${index},${adjustment})">Записать</button></div>`)}
function saveReceiptItem(index,adjustment){const name=document.getElementById('receiptItemName').value.trim(),amount=Number(document.getElementById('receiptItemAmount').value);if(!name||!Number.isFinite(amount))return;const xs=adjustment?receiptDraft.ocr.adjustments:receiptDraft.ocr.items;const x={...(xs[index]||{id:id()}),name,amount,review:false,corrected:true};if(index<0)xs.push(x);else xs[index]=x;receiptDraft.ocr.translations=[];receiptDraft.ocr.show_translation=false;closeModal();updateReceiptView()}
function removeReceiptItem(index,adjustment){confirmSmall('Удалить эту строку чека?',()=>{(adjustment?receiptDraft.ocr.adjustments:receiptDraft.ocr.items).splice(index,1);receiptDraft.ocr.translations=[];closeModal();updateReceiptView()})}
function addPurchase(){if(ocrBusy){showError('Дождитесь окончания OCR','Распознавание ещё выполняется');return}const name=document.getElementById('shop').value.trim(),amount=Number(document.getElementById('amount').value),date=document.getElementById('date').value,category=document.getElementById('customCategory').value.trim()||document.getElementById('category').value||inferCategory(name);if(!name||!Number.isFinite(amount)||amount<=0||!CashModel.validDate(date)){showError('Проверьте покупку','Укажите название, сумму больше нуля и дату. Категория определяется автоматически');return}if(receiptDraft?.error&&!document.getElementById('receiptManualConfirmed')?.checked){showError('Проверьте чек','Подтвердите ручной ввод после ошибки OCR');return}if(receiptDraft?.ocr){const missing=[...document.querySelectorAll('[data-ocr-review]')].some(x=>!x.checked);if(!receiptReviewValid()&&(receiptDraft.ocr.reviewedToken||missing||!document.getElementById('receiptItemsConfirmed')?.checked)){showOCRReview();return}receiptDraft.ocr.corrected={name,amount,date,items:structuredClone(receiptDraft.ocr.items),adjustments:structuredClone(receiptDraft.ocr.adjustments),confirmedAt:new Date().toISOString()}}
 if(purchaseInstallments&&CashModel.method(pay)!=='credit'){showError('Проверьте способ оплаты','Для рассрочки выберите credit');return}pendingPurchaseConfirm={id:id(),name,amount,date,category,dog_entry_id:d.dogEntries.find(e=>!e.deleted&&category==='Собака / '+e.name)?.id||'',installment_plan:purchaseInstallments?{count:purchaseInstallments}:null,category_manual:document.getElementById('category').dataset.manual==='true',method:CashModel.method(pay),cardId:document.getElementById('purchaseCard')?.value||d.cardId||'main',document_id:receiptDraft?.document_id||null,ocr:receiptDraft?.ocr?structuredClone(receiptDraft.ocr):null,receipt_items:structuredClone(receiptDraft?.ocr?.corrected?.items||[]),source:receiptDraft?'Чек / ручная проверка':'Ручной ввод'};modal(`<h3>Выберите статус покупки</h3><div class="row"><span dir="auto">${esc(name)}</span><b>${fmt(amount)}</b></div><p class="small">Категория: ${esc(category)} · ${methodLabel(pay)}</p><div class="stack purchase-status-buttons"><button onclick="choosePurchaseStatus('Совершено')">Совершено</button><button onclick="choosePurchaseStatus('Запланировано')">Запланировано</button></div><button class="compact" onclick="pendingPurchaseConfirm=null;closeModal()">Отмена</button>`)}
function choosePurchaseStatus(status){const x=pendingPurchaseConfirm;if(!x||!['Совершено','Запланировано'].includes(status))return;x.status=status;modal(`<h3>Вы уверены?</h3><div class="row"><span dir="auto">${esc(x.name)}</span><b>${fmt(x.amount)}</b></div><p class="small">${status==='Совершено'?'Совершено — в журнал покупок. Credit учитывается по дате списания.':'Запланировано — в планы и резервы, без фактического банковского списания.'}</p>${status==='Совершено'?`<details class="help"><summary>Банковское состояние отдельно</summary><label><input id="purchaseIncluded" type="checkbox"> Уже включена в сумму credit</label><label><input id="purchaseDebited" type="checkbox"> Уже списана банком</label><label>Дата проводки<input id="purchasePosted" type="date"></label><label>Дата банковского списания<input id="purchaseCharge" type="date" value="${CashModel.chargeDate(x,d)}"></label></details>`:''}<div id="purchaseConfirmationError" class="small red"></div><div class="actions"><button class="compact" onclick="pendingPurchaseConfirm=null;closeModal()">Отмена</button><button class="primary compact" onclick="confirmPurchaseSave()">Да</button></div>`)}

function viewReceipt(key){const x=d.purchases.find(x=>x.id===key);if(x?.document_id)openDocument(x.document_id);else if(x?.attachment&&/^data:image\/(png|jpeg|webp|gif);base64,/.test(x.attachment))modal('<img class="attachment" src="'+esc(x.attachment)+'" alt="Оригинал чека"><button onclick="closeModal()">Закрыть</button>')}
async function openDocument(key){const doc=await Storage.getDocument(key);if(!doc){modal('<h3>Оригинал не найден</h3><p class="small">Восстановите полную ZIP-копию с документами.</p><button onclick="closeModal()">Закрыть</button>');return}const url=URL.createObjectURL(doc.blob),kind=/pdf/i.test(doc.mime+doc.name)?'pdf':/csv|xlsx|sheet/i.test(doc.mime+doc.name)?'excel':'image';modal(`<h3>${esc(doc.name)}</h3>${kind==='image'?`<img class="attachment" src="${url}" alt="Оригинальный документ">`:kind==='pdf'?`<iframe title="Оригинал PDF" class="pdf-original" src="${url}"></iframe>`:'<p class="small">Excel / CSV: скачайте оригинал для просмотра в табличном приложении.</p>'}<div class="actions"><a class="compact" href="${url}" download="${esc(doc.name)}">Скачать оригинал</a><button class="compact" onclick="closeModal()">Закрыть</button></div>`);setTimeout(()=>URL.revokeObjectURL(url),300000)}
async function exportData(){await Storage.flush();download('Save-Cash-data-'+TODAY()+'.json','application/json',JSON.stringify({app:'Save Cash',schemaVersion:2,dataVersion:5,exportedAt:new Date().toISOString(),documentsIncluded:false,data:d},null,2))}
async function exportBackup(){try{await Storage.flush();const bytes=await CashBackup.create(d,await Storage.documents());download('Save-Cash-full-'+TODAY()+'.zip','application/zip',bytes)}catch(e){showError('Резервная копия не создана',e)}}
function showError(title,e){modal('<h3>'+esc(title)+'</h3><p class="small">'+esc(e.message||e)+'</p><button class="compact" onclick="closeModal()">Закрыть</button>')}
async function importData(file){if(!file)return;try{let data,documents=[];if(file.size>250*1024*1024)throw Error('Резервная копия больше 250 МБ. Разделите документы перед импортом.');const bytes=new Uint8Array(await file.arrayBuffer());if(bytes[0]===80&&bytes[1]===75){const unpacked=await CashBackup.parse(bytes);data=validData(unpacked.data);documents=unpacked.documents}else{const raw=JSON.parse(new TextDecoder().decode(bytes));if(raw.type==='save-cash-private-update'){await importPrivateUpdate(raw);return}if(raw.type==='save-cash-lesson-update'){await importLessonUpdate(raw);return}if(raw.type==='save-cash-data-patch'){await importDataPatch(raw);return}data=validData(raw)}const ids=new Set(documents.map(x=>x.id)),refs=[...[...data.purchases,...data.planned,...data.holidays].map(x=>x.document_id),...(data.documents||[]).map(x=>x.id),...data.bankStatements.flatMap(x=>x.document_ids||[])].filter(Boolean);for(const ref of refs)if(!ids.has(ref)&&!await Storage.getDocument(ref))throw Error('Нет документа '+ref+'. Нужна полная ZIP-копия.');confirmSmall('Восстановить данные? Текущий снимок будет сохранён.',async()=>{try{await Storage.flush();await Storage.backup('before-full-restore-'+TODAY(),d);data.initialized=true;await Storage.restore(data,documents);d=data;await Storage.migrateAttachments(d);await save('Восстановление полной копии');receiptDraft=null;closeModal();render()}catch(e){showError('Восстановление не выполнено',e)}})}catch(e){showError('Импорт не выполнен',e)}}
async function importDataPatch(raw){if(raw.app!=='Save Cash'||raw.version!==1)throw Error('Неизвестное обновление данных');const next=structuredClone(d);if(raw.lessonBills){validateLessons(raw.lessonBills);for(const b of raw.lessonBills){const i=next.lessonBills.findIndex(x=>x.id===b.id);if(i>=0)next.lessonBills[i]=b;else next.lessonBills.push(b)}}if(Number.isFinite(raw.educationFee)&&raw.educationFee>=0){next.educationFee=raw.educationFee;next.math=raw.educationFee}for(const u of raw.installmentUpdates||[]){const x=next.installments.find(x=>x.id===u.id);if(!x)continue;if(u.expected_charge_date&&CashModel.validDate(u.expected_charge_date))x.expected_charge_date=u.expected_charge_date;if(u.status)x.status=String(u.status);if(u.active!==undefined)x.active=!!u.active;if(u.included_in_statement!==undefined)x.included_in_statement=!!u.included_in_statement}if(raw.childName)next.childName=String(raw.childName);if(raw.lessonRecipient)next.lessonRecipient=String(raw.lessonRecipient);validData(next);confirmSmall('Обновить указанные счета и даты? Баланс, покупки и остальные записи сохранятся.',async()=>{await Storage.backup('before-data-patch-'+TODAY(),d);d=next;await save('Уточнение исходных счетов');closeModal();render()})}
function documentButton(ref,legacy=false){if(!ref&&!legacy)return '';if(legacy)return '<span class="small">Чек в прежней копии</span>';const meta=(d.documents||[]).find(x=>x.id===ref),name=meta?.name||'',mime=meta?.mime||'',type=/pdf/i.test(name+mime)?'PDF':/csv|xlsx|sheet/i.test(name+mime)?'Excel':'Фото';return `<button class="document-link" onclick="openDocument('${ref}')" title="Открыть оригинал">${type==='Фото'?uiIcon('gallery'):type}</button>`}
function bankReconciliationHTML(){const run=d.reconciliationRuns.find(x=>x.id===bankRunId)||d.reconciliationRuns.filter(x=>['draft','reviewed','final'].includes(x.status)).at(-1);return `<div class="row"><span class="small">Импортируйте выписку перед списанием карты. Финансы изменятся после двух подтверждений.</span><button class="compact" onclick="showReconLog()">↶ Лог</button></div><input id="bankFiles" type="file" multiple accept="image/*,.pdf,.csv,.xlsx" hidden onchange="importBankFiles(this.files)"><button class="compact primary" onclick="document.getElementById('bankFiles').click()">＋ Выписка</button><span id="bankImportProgress" class="small"></span>${d.bankStatements.length?`<div class="form-row"><label>Сохранённые выписки</label><select onchange="selectBankStatement(this.value)"><option value="">Выбрать документ</option>${d.bankStatements.map(s=>`<option value="${s.id}">${esc(s.name)} · ${esc(s.charge_date)} · ${s.status==='full'?'полная':'частичная'}</option>`).join('')}</select></div>`:'<p class="small">Фотографии, PDF, CSV и XLSX хранятся на устройстве вместе с оригиналами. Без импортированных документов демонстрационные операции не создаются.</p>'}${run?`<div class="small">${run.full?'Полная':'Частичная'} выписка · ${esc(run.date)}${run.status==='final'?' · окончательно подтверждена':''}</div><div id="bankComparisonList">${run.decisions.map(x=>comparisonCard(run,x)).join('')}</div><div class="actions">${run.status==='final'?`<button class="compact" onclick="reopenBankRun('${run.id}')">Повторная сверка</button><button class="compact danger" onclick="rollbackBankRun('${run.id}')">Откатить сверку</button>`:`<button class="compact primary" onclick="beginBankReview('${run.id}')">Принять сверку</button>`}</div>`:''}`}
function comparisonCard(run,x){const confirmed=x.manual&&x.choice,color=confirmed?'green':x.color,left=x.left,right=x.right,locked=run.status==='final';const side=(name,value,side,available)=>`<div class="compare-half ${x.choice===side?'chosen':''}"><div class="small">${name}</div><div class="compare-name" dir="auto">${esc(value?.name||'Нет записи')}</div><button class="side-amount" ${!available||locked?'disabled':''} onclick="chooseBankSide('${run.id}','${x.id}','${side}')" aria-label="Выбрать ${side==='left'?'мою':'банковскую'} сумму">${value?fmt(side==='right'?(value.amount_ils??value.amount):value.amount):'—'} ${x.choice===side?'<span class="green">✓</span>':''}</button><div class="small">${esc(side==='right'?value?.operation_date||'Дата не подтверждена':value?.date||'Дата не указана')}</div>${documentButton(value?.document_id,value?.attachment)}${side==='left'&&value&&!locked?`<button class="icon" aria-label="Исправить мою запись сверки" onclick="editLeftReconciliation('${run.id}','${x.id}')">✎</button>`:''}</div>`;return `<article class="comparison ${color}" data-decision="${x.id}"><div class="row"><b dir="auto">${esc(left?.name||right?.name||'Операция')}</b><span class="small">${confirmed?'✓ Подтверждено вручную':color==='green'?'✓ Авто':color==='yellow'?'◷ Даты':'! Требует решения'}</span></div><div class="compare-halves">${side('Моя запись',left,'left',!!left)}${side('Выписка банка',right,'right',!!right)}</div><div class="small comparison-reason">${esc(x.reason)}${right?.conflicting_imports?.length?'<br>В повторном импорте тот же ID имеет другие значения: '+right.conflicting_imports.map(v=>esc(v.name)+' · '+fmt(v.amount)+' · '+esc(v.operation_date)).join('; ')+'<br>Откройте «Банк / комиссия» и укажите подтверждённую сумму.':''}${x.fee_for?'<br>Комиссия связана с '+esc(x.fee_for):''}${x.fee_included?'<br>Комиссия уже включена в итог':''}</div>${x.choice==='exclude'?'<div class="small green">Не отдельное списание · 0,00 ₪</div>':''}${locked?`<button class="compact" onclick="undoBankDecision('${run.id}','${x.id}')">Отменить решение</button>`:`<div class="comparison-actions"><button class="compact" onclick="focusBankDecision('${run.id}','${x.id}')">Подробнее</button>${!left?`<button class="compact" onclick="associateBankRecord('${run.id}','${x.id}')">Связать с записью</button>`:''}<button class="compact" onclick="editBankDecision('${run.id}','${x.id}')">✎ Банк / комиссия</button><button class="compact" onclick="chooseBankSide('${run.id}','${x.id}','exclude')">Не отдельная операция</button></div>`}</article>`}
function refreshBankUI(){const body=document.querySelector('[data-section="bankrecon"] .section-body');if(body)body.innerHTML=bankReconciliationHTML();if(reconFocusId){const run=d.reconciliationRuns.find(x=>x.id===bankRunId),decision=run?.decisions.find(x=>x.id===reconFocusId);if(decision)modal(`<h3>Проверка операции</h3>${comparisonCard(run,decision)}<button class="compact" onclick="closeFocusedDecision()">Назад к сверке</button>`)}}
function chooseBankSide(runId,decisionId,side){try{Reconciliation.choose(d,runId,decisionId,side);bankRunId=runId;save('Выбор стороны сверки');refreshBankUI()}catch(e){showError('Выбор не применён',e)}}
function focusBankDecision(runId,key){bankRunId=runId;reconFocusId=key;refreshBankUI()}
function closeFocusedDecision(){reconFocusId=null;closeModal();refreshBankUI()}
async function importBankFiles(files){if(!files?.length)return;bankDraft={documents:[],rows:[],unparsed:[],charge_date:d.statementDate,cardId:d.cardId||'main',status:'partial'};const progress=document.getElementById('bankImportProgress');try{for(const file of files){progress.textContent=' Читаем '+file.name;const meta=await Storage.storeDocument(file,'statement');registerDocument(meta);if(d.bankStatements.some(s=>(s.document_ids||[]).includes(meta.id))||bankDraft.documents.some(x=>x.id===meta.id)){progress.textContent=' Уже импортировано: '+file.name;continue}const parsed=await DocumentEngine.readFile(file,p=>progress.textContent=' '+file.name+' · '+p.status+' '+Math.round((p.progress||0)*100)+'%');bankDraft.documents.push({...meta,text:parsed.text||'',kind:parsed.kind});bankDraft.rows.push(...parsed.rows.map(row=>({...row,document_id:meta.id})));bankDraft.unparsed.push(...parsed.unparsed.map(text=>({document_id:meta.id,text})));}if(!bankDraft.documents.length){progress.textContent=' Эти документы уже импортированы; дубликаты не созданы.';bankDraft=null;return}showBankDraft()}catch(e){showError('Импорт остановлен. Финансы не изменены',e)}}
function showBankDraft(){modal(`<h3>Проверьте выписку</h3><div class="two"><div class="form-row"><label>Дата списания с банка</label><input id="bankChargeDate" type="date" value="${esc(bankDraft.charge_date)}"></div><div class="form-row"><label>Последние 4 цифры карты</label><input id="bankCard4" inputmode="numeric" maxlength="4" value="${esc(bankDraft.cardLast4||'')}"></div></div><div class="form-row"><label>Статус документа</label><select id="bankDraftStatus"><option value="partial" ${bankDraft.status==='partial'?'selected':''}>Частичная выписка</option><option value="full" ${bankDraft.status==='full'?'selected':''}>Полная выписка</option></select></div><p class="small">Проверьте операции. Суммы в ₪; возвраты — отрицательные. Покупки и банковское списание могут иметь разные даты.</p><div class="bank-draft-rows">${bankDraft.rows.map((r,i)=>`<div class="bank-draft-row"><div class="two"><input data-bank-field="name" data-bank-index="${i}" dir="auto" value="${esc(r.name)}" aria-label="Магазин ${i+1}"><input data-bank-field="amount" data-bank-index="${i}" type="number" step=".01" value="${r.amount}" aria-label="Сумма ${i+1}"><input data-bank-field="operation_date" data-bank-index="${i}" type="date" value="${esc(r.operation_date||'')}" aria-label="Дата операции ${i+1}"><input data-bank-field="currency" data-bank-index="${i}" value="${esc(r.currency||'ILS')}" aria-label="Валюта ${i+1}"></div><div class="small">${documentButton(r.document_id)} ${r.needs_review?'Нужно проверить оригинал':'Из структурированной таблицы'}</div><label class="small"><input data-bank-checked="${i}" type="checkbox" ${r.needs_review?'':'checked'}> Строка проверена по оригиналу</label><button class="payment-remove" onclick="removeBankDraftRow(${i})">Не операция</button></div>`).join('')}</div><button class="compact" onclick="addBankDraftRow()">＋ Операция</button>${bankDraft.unparsed.length?`<details class="help"><summary>Нераспознанные строки (${bankDraft.unparsed.length})</summary>${bankDraft.unparsed.map(x=>`<div dir="auto" class="small">${esc(x.text)}</div>`).join('')}<p>Добавьте недостающие операции вручную. Частичный документ не считается окончательной выпиской.</p></details>`:''}<div id="bankDraftError" class="small red"></div><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="saveBankDraft()">Подтвердить распознавание</button></div>`)}
function syncBankDraft(){bankDraft.charge_date=document.getElementById('bankChargeDate').value;bankDraft.status=document.getElementById('bankDraftStatus').value;bankDraft.cardLast4=document.getElementById('bankCard4').value.replace(/\D/g,'').slice(-4);bankDraft.cardId=BudgetFeatures.resolveCard(d,bankDraft.cardLast4);document.querySelectorAll('[data-bank-field]').forEach(e=>{const r=bankDraft.rows[Number(e.dataset.bankIndex)],k=e.dataset.bankField;r[k]=k==='amount'?Number(e.value):e.value});document.querySelectorAll('[data-bank-checked]').forEach(e=>bankDraft.rows[Number(e.dataset.bankChecked)].needs_review=!e.checked)}
function addBankDraftRow(){syncBankDraft();bankDraft.rows.push({id:id(),name:'',amount:0,currency:'ILS',operation_date:'',transaction_id:'',needs_review:true,document_id:bankDraft.documents[0]?.id});showBankDraft()}
function removeBankDraftRow(i){syncBankDraft();bankDraft.rows.splice(i,1);showBankDraft()}
function saveBankDraft(){syncBankDraft();try{if(!CashModel.validDate(bankDraft.charge_date)||!bankDraft.rows.length)throw Error('Укажите дату списания и добавьте операции');for(const r of bankDraft.rows)if(!r.name.trim()||!Number.isFinite(r.amount)||!CashModel.validDate(r.operation_date))throw Error('Проверьте магазин, сумму и дату каждой операции');if(bankDraft.cardLast4)BudgetFeatures.registerCard(d,bankDraft.cardLast4);const statement={id:id(),name:bankDraft.documents.map(x=>x.name).join(', '),hash:bankDraft.documents.map(x=>x.hash).join(':'),cardId:bankDraft.cardId,cardLast4:bankDraft.cardLast4,charge_date:bankDraft.charge_date,status:bankDraft.status,document_ids:bankDraft.documents.map(x=>x.id),sources:bankDraft.documents,unparsed:bankDraft.unparsed,rows:bankDraft.rows,importedAt:new Date().toISOString()};d.bankStatements.push(statement);bankRunId=Reconciliation.prepare(d,statement.id).id;bankDraft=null;save('Импорт банковской выписки');closeModal();render()}catch(e){document.getElementById('bankDraftError').textContent=e.message}}
function selectBankStatement(key){if(!key)return;const statement=d.bankStatements.find(x=>x.id===key),run=d.reconciliationRuns.filter(x=>x.statement_id===key&&['draft','reviewed','final'].includes(x.status)).at(-1);bankRunId=run?.id||Reconciliation.prepare(d,statement.id).id;refreshBankUI()}
function associateBankRecord(runId,decisionId){const run=d.reconciliationRuns.find(x=>x.id===runId),xs=Reconciliation.leftRecords(d,run.date,run.cardId);modal(`<h3>Выберите исходную запись</h3><div class="stack">${xs.map(x=>`<button class="compact" onclick="saveBankAssociation('${runId}','${decisionId}','${x.id}')">${esc(x.name)} · ${fmt(x.amount)} · ${esc(x.date)}</button>`).join('')||'<p class="small">Нет записей для этой карты и даты.</p>'}<button class="compact" onclick="closeModal()">Отмена</button></div>`)}
function saveBankAssociation(runId,decisionId,leftId){try{Reconciliation.associate(d,runId,decisionId,leftId);save('Ручная связь с банком');closeModal();refreshBankUI()}catch(e){showError('Связь не создана',e)}}
function editBankDecision(runId,decisionId){const run=d.reconciliationRuns.find(x=>x.id===runId),x=run.decisions.find(x=>x.id===decisionId);if(!x.right)return;const r=x.right;modal(`<h3>Банковская строка</h3><div class="form-row"><label>Название</label><input id="bankEditName" dir="auto" value="${esc(r.name)}"></div><div class="two"><div class="form-row"><label>Сумма в исходной валюте</label><input id="bankEditAmount" type="number" step=".01" value="${r.amount}"></div><div class="form-row"><label>Дата операции</label><input id="bankEditDate" type="date" value="${esc(r.operation_date)}"></div></div><div class="form-row"><label>Фактическая сумма банка в ₪ · при конвертации</label><input id="bankEditILS" type="number" step=".01" value="${r.amount_ils??''}"></div><div class="form-row"><label>Отдельная комиссия к операции</label><select id="bankFeeFor"><option value="">Не комиссия</option>${run.decisions.filter(v=>v.id!==decisionId&&v.right).map(v=>`<option value="${v.right.id}" ${x.fee_for===v.right.id?'selected':''}>${esc(v.right.name)} · ${fmt(v.right.amount)}</option>`).join('')}</select></div><label class="small"><input id="bankFeeIncluded" type="checkbox" ${x.fee_included?'checked':''}> Комиссия уже входит в банковскую сумму исходной покупки</label><p class="small">Не отмечайте включение без подтверждения документом. Отдельная комиссия сохраняется банковской строкой.</p><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="compact primary" onclick="saveBankDecision('${runId}','${decisionId}')">Сохранить</button></div>`)}
function saveBankDecision(runId,decisionId){const run=d.reconciliationRuns.find(x=>x.id===runId),x=run.decisions.find(x=>x.id===decisionId),amount=Number(document.getElementById('bankEditAmount').value),date=document.getElementById('bankEditDate').value;if(!Number.isFinite(amount)||!CashModel.validDate(date))return;x.original_right??=structuredClone(x.right);x.right.name=document.getElementById('bankEditName').value.trim()||x.right.name;x.right.amount=amount;x.right.operation_date=date;const ils=document.getElementById('bankEditILS').value;if(ils!=='')x.right.amount_ils=Number(ils);else delete x.right.amount_ils;x.fee_for=document.getElementById('bankFeeFor').value||null;x.fee_included=document.getElementById('bankFeeIncluded').checked;x.choice=x.fee_included?'exclude':null;x.manual=x.fee_included;x.color='pink';x.reason=x.fee_for?'Комиссия: проверьте включение в исходный платёж':'Банковская строка исправлена · выберите сумму';run.status='draft';delete run.reviewFingerprint;save('Уточнение банка / комиссии');closeModal();refreshBankUI()}
function beginBankReview(runId){try{const review=Reconciliation.review(d,runId);save('Предварительная проверка сверки');if(!review.ok){modal(`<h3>Не решено: ${review.unresolved.length}</h3><p class="small">Выберите операцию, чтобы открыть только её сравнение.</p><div class="stack">${review.unresolved.map(x=>`<button class="compact" onclick="focusBankDecision('${runId}','${x.id}')">${esc(x.name)}</button>`).join('')}<button class="compact" onclick="closeModal()">Назад</button></div>`);return}const run=d.reconciliationRuns.find(x=>x.id===runId),next=structuredClone(d);Reconciliation.finalize(next,runId,review.fingerprint);const before=CashModel.calculate(d),after=CashModel.calculate(next);modal(`<h3>Итоговая проверка</h3><p class="small">${review.partial?'Выписка остаётся частичной. Известная часть общей суммы сохраняется с исключением покрытых строк.':'Полная выписка заменит общую сумму для этой карты и даты.'}</p>${item('Выбрано по операциям',review.total)}${item('Прогноз до сверки',before.forecast)}${item('Прогноз после сверки',after.forecast)}<p class="small">Документы и исходные записи сохранятся. Решения можно откатить через лог.</p><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="finalizeBankReview('${runId}','${review.fingerprint}')">Подтверждаю окончательно</button></div>`)}catch(e){showError('Сверка не завершена',e)}}
function finalizeBankReview(runId,token){try{const before=CashModel.calculate(d).forecast;Reconciliation.finalize(d,runId,token);const entry=d.reconciliationLog.at(-1);entry.forecast_before=before;entry.forecast_after=CashModel.calculate(d).forecast;entry.forecast_delta=entry.forecast_after-before;save('Окончательно подтверждена сверка');reconFocusId=null;closeModal();render()}catch(e){showError('Нужна повторная проверка',e)}}
function rollbackBankRun(runId){confirmSmall('Откатить всю сверку? Оригиналы и покупки сохранятся.',()=>{Reconciliation.rollback(d,runId);save('Откат сверки');closeModal();render()})}
function reopenBankRun(runId){bankRunId=Reconciliation.reopen(d,runId).id;save('Повторная сверка');refreshBankUI()}
function undoBankDecision(runId,decisionId){confirmSmall('Отменить это решение и вернуть исходную сумму?',()=>{Reconciliation.undoDecision(d,runId,decisionId);save('Отмена решения');closeModal();render()})}
function showReconLog(){modal(`<h3>История сверки</h3>${d.reconciliationLog.slice().reverse().map(x=>`<div class="purchase small"><b>${esc(x.event)}</b> · ${esc(x.at)}<br>${esc(x.operation)}<br>Моя ${x.manual_amount===null?'—':fmt(x.manual_amount)} · банк ${x.bank_amount===null?'—':fmt(x.bank_amount)} · ${esc(x.side||'')}<br>Выписка ${esc(x.statement_id)}${x.fee_for?'<br>Комиссия: '+esc(x.fee_for):''}${x.forecast_delta!==undefined?'<br>Изменение прогноза: '+fmt(x.forecast_delta):''}${x.decision_id?`<button class="compact" onclick="undoBankDecision('${x.run_id}','${x.decision_id}')">Отменить решение</button>`:''}</div>`).join('')||'<p class="small">Решений пока нет.</p>'}<button class="compact" onclick="closeModal()">Закрыть</button>`)}
function editableItem(collection,x){if(collection!=='subs')return legacyEditableItem(collection,x);return `<div class="purchase ${x.active===false?'muted':''}"><div class="row"><span>${esc(x.name)}<div class="small">${esc(x.expected_charge_date||('Ориентировочно '+(x.day||'—')+'-е'))} · ${esc(x.periodicity||'monthly')} · ${methodLabel(x.method)}</div></span><span class="field"><b class="money">${fmt(x.amount)}</b><button class="icon" onclick="editRecurring('${x.id}')">✎</button><button class="icon danger" onclick="removeItem('subs','${x.id}')">×</button></span></div><label class="small"><input type="checkbox" ${x.active!==false?'checked':''} onchange="setRecurringActive('${x.id}',this.checked)"> Учитывать</label> <label class="small"><input type="checkbox" ${x.included_in_statement?'checked':''} onchange="included('${x.id}',this.checked)"> В выписке</label></div>`}
function setRecurringActive(key,value){d.subs.find(x=>x.id===key).active=value;save('Включение / отключение абонплаты');render()}
function editRecurring(key){const x=d.subs.find(x=>x.id===key)||{id:'',name:'',amount:0,periodicity:'monthly',expected_charge_date:d.statementDate,method:'credit',included_in_statement:false,active:true};modal(`<h3>Абонплата</h3><div class="form-row"><label>Название</label><input id="recurringName" value="${esc(x.name)}"></div><div class="two"><div class="form-row"><label>Сумма, ₪</label><input id="recurringAmount" type="number" step=".01" min="0" value="${x.amount}"></div><div class="form-row"><label>Дата банковского списания</label><input id="recurringDate" type="date" value="${esc(x.expected_charge_date||d.statementDate)}"></div></div><div class="two"><select id="recurringPeriod">${[['monthly','Ежемесячно'],['weekly','Еженедельно'],['yearly','Ежегодно']].map(([v,label])=>`<option value="${v}" ${x.periodicity===v?'selected':''}>${label}</option>`).join('')}</select><select id="recurringMethod">${['credit','debit','cash'].map(v=>`<option ${CashModel.method(x.method)===v?'selected':''}>${v}</option>`).join('')}</select></div>${editorCardHTML('recurringCard',x.cardId)}<label class="small"><input id="recurringIncluded" type="checkbox" ${x.included_in_statement?'checked':''}> В сумме credit</label><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="compact primary" onclick="saveRecurring('${key||''}')">Сохранить</button></div>`)}
function saveRecurring(key){const name=document.getElementById('recurringName').value.trim(),amount=Number(document.getElementById('recurringAmount').value),date=document.getElementById('recurringDate').value;if(!name||!Number.isFinite(amount)||amount<0||!CashModel.validDate(date))return;let x=d.subs.find(x=>x.id===key);if(!x){x={id:'sub-'+id(),active:true,source:'Ручной ввод'};d.subs.push(x)}Object.assign(x,{name,amount,expected_charge_date:date,periodicity:document.getElementById('recurringPeriod').value,cardId:document.getElementById('recurringCard').value,method:document.getElementById('recurringMethod').value,included_in_statement:document.getElementById('recurringIncluded').checked});save('Редактирование абонплаты');closeModal();render()}
function installmentsHTML(){return `<details class="help"><summary>Зачем две отметки?</summary>«Учитывать» включает обязательство. «В выписке» исключает отдельное вычитание: оно уже в общей банковской сумме. Выключение строки не уменьшает сумму самой выписки.</details>${d.installments.filter(x=>!x.deleted&&Number(x.payment_count)!==1).map(x=>`<div class="purchase"><div class="row"><span><b dir="auto">${esc(x.merchant)}</b><div class="small">${x.payment_index} из ${x.payment_count} · ${esc(x.expected_charge_date)}</div></span><span class="field"><b class="money">${fmt(x.amount_per_payment)}</b><button class="icon" onclick="editInstallment('${x.id}')">✎</button></span></div><div class="small">${esc(x.status)} · ${esc(x.source||'Ручной ввод')}${CashModel.installmentUnverified(x)?`<button class="compact" onclick="reviewInstallment('${x.id}')">Подтвердить по выписке</button>`:''}<br>Полная сумма: ${fmt(x.full_amount??x.amount_per_payment*x.payment_count)}${x.full_amount===undefined?' · расчётная':''}<br>После этого платежа: ${Math.max(0,x.payment_count-x.payment_index)} × ${fmt(x.amount_per_payment)} = ${fmt(CashModel.remaining(x))}</div><label class="small"><input type="checkbox" ${x.included_in_statement?'checked':''} onchange="setInstallment('${x.id}','included_in_statement',this.checked)"> В сумме выписки</label> <label class="small"><input type="checkbox" ${x.active?'checked':''} onchange="setInstallment('${x.id}','active',this.checked)"> Учитывать</label><details class="small"><summary>Будущие даты</summary>${CashModel.installmentSchedule(x).filter(p=>p.date>d.balanceDate).map(p=>`<div>${p.index}/${x.payment_count} · ${esc(p.date)} · ${fmt(p.amount)}</div>`).join('')||'<div>Будущих платежей нет</div>'}</details></div>`).join('')}<button class="compact" onclick="editInstallment()">＋ Добавить рассрочку</button>`}
function editInstallment(key){const x=d.installments.find(x=>x.id===key)||{merchant:'',amount_per_payment:0,payment_index:1,payment_count:2,expected_charge_date:d.statementDate,status:'Требует сверки'};modal(`<h3>Рассрочка</h3><label>Дата покупки<input id="instPurchaseDate" type="date" value="${esc(x.purchase_date||'')}"></label>${editorCardHTML('instCard',x.cardId)}<label>Способ оплаты<select id="instMethod">${['credit','debit','cash'].map(m=>`<option ${CashModel.method(x.method)===m?'selected':''}>${m}</option>`).join('')}</select></label><div class="form-row"><label>Магазин</label><input id="instMerchant" dir="auto" value="${esc(x.merchant)}"></div><div class="two"><div class="form-row"><label>Очередной платёж, ₪</label><input id="instAmount" type="number" min="0" step=".01" value="${x.amount_per_payment}"></div><div class="form-row"><label>Полная сумма, если подтверждена</label><input id="instFull" type="number" min="0" step=".01" value="${x.full_amount??''}"></div><div class="form-row"><label>Номер платежа</label><input id="instIndex" type="number" min="1" value="${x.payment_index}"></div><div class="form-row"><label>Всего платежей</label><input id="instCount" min="2" type="number" min="1" value="${x.payment_count}"></div></div><div class="form-row"><label>Дата списания текущего платежа</label><input id="instDate" type="date" value="${esc(x.expected_charge_date)}"></div><div class="form-row"><label>Статус</label><select id="instStatus"><option ${x.status==='Требует сверки'?'selected':''}>Требует сверки</option><option ${x.status==='Подтверждено'?'selected':''}>Подтверждено</option></select></div><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="compact primary" onclick="saveInstallment('${key||''}')">Сохранить</button></div>`)}
function saveInstallment(key){const merchant=document.getElementById('instMerchant').value.trim(),amount=Number(document.getElementById('instAmount').value),index=Number(document.getElementById('instIndex').value),count=Number(document.getElementById('instCount').value),date=document.getElementById('instDate').value,full=document.getElementById('instFull').value;if(!merchant||full!==''&&(!Number.isFinite(Number(full))||Number(full)<0)||!Number.isFinite(amount)||amount<0||!Number.isInteger(index)||!Number.isInteger(count)||index<1||count<2||count<index||!CashModel.validDate(date))return;let x=d.installments.find(x=>x.id===key);if(!x){x={id:id(),active:true,included_in_statement:false,source:'Ручной ввод'};d.installments.push(x)}d.featureHistory.push({id:id(),at:new Date().toISOString(),event:'Редактирование рассрочки',before:structuredClone(x)});if(x.schedule)(x.schedule_history??=[]).push({at:new Date().toISOString(),schedule:structuredClone(x.schedule)});delete x.schedule;Object.assign(x,{merchant,amount_per_payment:amount,payment_index:index,payment_count:count,expected_charge_date:date,purchase_date:document.getElementById('instPurchaseDate').value,method:document.getElementById('instMethod').value,cardId:document.getElementById('instCard').value,status:document.getElementById('instStatus').value});x.confirmed=x.status==='Подтверждено';if(full!=='')x.full_amount=Number(full);else delete x.full_amount;if(x.full_amount>0&&count>=2&&count<=12){x.schedule=BudgetFeatures.schedule(x.full_amount,count,CashModel.addMonths(date,1-index));x.amount_per_payment=x.schedule[index-1].amount}save('Изменение рассрочки');closeModal();render()}
function cibusExtrasHTML(){return `<div class="row"><span class="small">Источник оплаты личного участия</span><select class="compact" onchange="setCibusMethod(this.value)">${[['unconfirmed','Не подтверждён'],['credit','credit'],['debit','debit'],['cash','Наличные']].map(([v,label])=>`<option value="${v}" ${d.cibusMethod===v?'selected':''}>${label}</option>`).join('')}</select></div><div class="actions"><button class="compact" onclick="autoCibusDays()">Дни по календарю</button><button class="compact" onclick="cibusTemplate()">10 рабочих + 2 выходных</button><button class="compact" onclick="addCibusActual()">＋ Фактический обед</button></div><div class="small">Выходных: ${d.cibusWeekends||0}. Не подтверждённый источник не считается банковским списанием.</div>${d.cibusActual.map(x=>`<div class="small">${esc(x.date)} · обед ${fmt(x.cost)} · моё участие ${fmt(Math.max(0,x.cost-x.employer))}</div>`).join('')}`}
function setCibusMethod(value){d.cibusMethod=value;save('Источник оплаты Cibus');render()}
function autoCibusDays(){const days=CashModel.workingDays(d.periodStart,d.periodEnd);confirmSmall('Использовать календарную оценку: '+days.work+' рабочих и '+days.weekend+' выходных?',()=>{d.cibusDays=days.work;d.cibusWeekends=days.weekend;save('Календарная оценка Cibus');render()})}
function cibusTemplate(){d.cibusDays=10;d.cibusWeekends=2;const v=CashModel.cibus(d);d.cibus50=v.n50;d.cibusOrdinary=v.ordinary;save('Шаблон дней Cibus');render()}
function addCibusActual(){modal(`<h3>Фактический обед</h3><div class="form-row"><label>Дата</label><input id="cibusFactDate" type="date" value="${TODAY()}"></div><div class="two"><div class="form-row"><label>Стоимость, ₪</label><input id="cibusFactCost" type="number" step=".01" min="0"></div><div class="form-row"><label>Участие работодателя, ₪</label><input id="cibusEmployer" type="number" step=".01" min="0" value="38"></div></div><p class="small">Этот обед заменяет один день обычного обеда в калькуляторе, а не добавляет отдельную покупку.</p><div id="cibusFactError" class="small red"></div><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="compact primary" onclick="saveCibusActual()">Записать</button></div>`)}
function saveCibusActual(){const date=document.getElementById('cibusFactDate').value,cost=Number(document.getElementById('cibusFactCost').value),employer=Number(document.getElementById('cibusEmployer').value);if(!CashModel.validDate(date)||!Number.isFinite(cost)||cost<0||!Number.isFinite(employer)||employer<0)return;if(d.cibusActual.some(x=>x.date===date)){document.getElementById('cibusFactError').textContent='Обед на эту дату уже записан';return}if(d.cibusActual.length+1>d.cibusDays-d.cibus50){document.getElementById('cibusFactError').textContent='Сначала увеличьте число рабочих дней';return}d.cibusActual.push({id:id(),date,cost,employer});d.cibusOrdinary=Math.max(d.cibusOrdinary,d.cibusActual.length);save('Фактический обед Cibus');closeModal();render()}
function reconciliationHTML(){const all=CashModel.calculate(d).rows,collator=new Intl.Collator('ru',{numeric:true});let rows=all.filter(x=>!ledgerQuery||[x.name,x.source].some(s=>String(s).toLowerCase().includes(ledgerQuery.toLowerCase())));rows.sort((a,b)=>{const primary=ledgerSort.key==='amount'?a.amount-b.amount:collator.compare(String(a[ledgerSort.key]||''),String(b[ledgerSort.key]||''));return (ledgerSort.asc?1:-1)*(primary||collator.compare(a.name,b.name)||a.amount-b.amount)});return `<div class="row ledger-tools"><span class="small">Одна операция — одно списание. «В выписке» учтено общей банковской суммой.</span><button class="compact narrow" onclick="resetLedgerFilter()">Сбросить фильтр</button></div><input class="ledger-search" placeholder="Найти статью или источник" value="${esc(ledgerQuery)}" oninput="setLedgerQuery(this.value)"><table class="ledger-table"><thead><tr>${[['name','Статья'],['amount','Сумма'],['source','Источник']].map(([key,title])=>`<th><button onclick="sortLedger('${key}')">${title}${ledgerSort.key===key?(ledgerSort.asc?' ↑':' ↓'):''}</button></th>`).join('')}<th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.name)}<div class="small">${esc(x.date)}${x.included?' · отдельно 0 ₪':''}</div></td><td>${fmt(x.amount)}</td><td>${esc(x.source)}<div class="small">${esc(x.status)}</div></td><td><button class="icon" aria-label="Изменить статью ${esc(x.name)}" onclick="editLedgerRow('${x.id}')">✎</button><button class="icon danger" aria-label="Удалить статью ${esc(x.name)}" onclick="deleteLedgerRow('${x.id}')">×</button></td></tr>`).join('')}</tbody></table><button class="compact" onclick="exportLedger()">Скачать CSV</button>`}
function sortLedger(key){ledgerSort={key,asc:ledgerSort.key===key?!ledgerSort.asc:key!=='amount'};refreshLedger()}
function setLedgerQuery(value){ledgerQuery=value;refreshLedger(true)}
function resetLedgerFilter(){ledgerQuery='';ledgerSort={key:'name',asc:true};refreshLedger()}
function refreshLedger(keepFocus=false){const target=document.querySelector('[data-section="reconciliation"] .section-body');if(target){target.innerHTML=reconciliationHTML();if(keepFocus){const input=target.querySelector('input');input.focus();input.setSelectionRange(input.value.length,input.value.length)}}}
function editLedgerRow(key){const row=CashModel.calculate(d).rows.find(x=>x.id===key)||CashModel.forecastBridge(d).futureRows.find(x=>x.id===key),ref=row?.ref;if(!ref)return;if(ref.collection==='purchases')return editPurchase(ref.id);if(ref.collection==='singleCardEntries')return editSingleCardEntry(ref.id);if(['dogEntries','menoraEntries'].includes(ref.collection))return editFeatureEntry(ref.collection,ref.id);if(ref.collection==='fixedPayments')return editFixedPayment(ref.id);if(ref.collection==='subs')return editRecurring(ref.id);if(ref.collection==='installments')return editInstallment(ref.id);if(ref.collection==='lessonBills'){const bill=d.lessonBills.find(x=>x.id===ref.id);return editLesson(bill.id,bill.subject)}if(ref.collection)return editRecord(ref.collection,ref.id);if(ref.key==='menoraScheme')return editMenoraScheme();if(ref.key==='balance')return editBankBalance();if(ref.key==='cibusDays'){goView('cibus');return}if(ref.key)return editMoneyKey(ref.key,row.name);showError('Редактируйте первичный источник','Откройте банковскую сверку или расчёт исходной статьи.')}
function deleteLedgerRow(key){const row=CashModel.calculate(d).rows.find(x=>x.id===key);if(!row)return;if(['statement','history'].includes(row.kind)){modal(`<h3>Банковская сумма выписки</h3><p class="small">Удаление отображаемой строки не отменяет списание банка. Для исправления измените исходную выписку и подтвердите сверку.</p><button class="compact" onclick="closeModal()">Отмена</button><button class="compact" onclick="editMoneyKey('statementTotal','Сумма выписки')">Исправить источник</button>`);return}confirmSmall('Удалить эту статью?',()=>{CashModel.removeRecord(d,row.ref?.collection?row.ref:{row_id:row.id});save('Удаление статьи из будущего расчёта');closeModal();render()})}
function reportHTML(){const groups={};for(const x of CashModel.unique(d.purchases).filter(x=>CashModel.inPeriod(d,x.date)&&CashModel.belongs(d,x)))(groups[x.name]??=[]).push(x);return `<details class="gray" open><summary><b>По магазинам</b></summary>${Object.entries(groups).sort(([a],[b])=>a.localeCompare(b,'ru')).map(([name,xs])=>`<div class="row"><span dir="auto">${esc(name)}<div class="small">Операций: ${xs.length}</div></span><b class="money">${fmt(sum(xs))}</b></div>`).join('')||'<div class="small">Покупок пока нет.</div>'}</details>${categoryReportHTML()}`}
let graphPeriods=[];
function chartHTML(){const current={id:'current',name:'Текущий период',from:d.periodStart,to:d.periodEnd,total:CashModel.calculate(d).rows.filter(x=>CashModel.method(x.method)==='credit'&&!x.included&&x.kind!=='history').reduce((s,x)=>s+x.amount,0),entries:CashModel.unique(d.purchases).filter(x=>CashModel.method(x.method)==='credit'&&CashModel.inPeriod(d,x.date)&&CashModel.belongs(d,x)),forecast:true};const all=[...d.history,...d.periodArchive.map(x=>({...x,name:x.from+'–'+x.to,entries:x.purchases})),current],ids=d.selectedPeriods.length?d.selectedPeriods:[...all.slice(-2).map(x=>x.id)];graphPeriods=all.filter(x=>ids.includes(x.id));const colors=['#19835c','#4c78a8','#bc7b36','#935f9c'],max=Math.max(1,...graphPeriods.map(x=>Number(x.total)||0));const xPos=day=>35+day/32*285,yPos=value=>145-value/max*118;const plots=graphPeriods.map((period,i)=>{const rows=(period.entries||[]).filter(x=>!CashModel.excluded(x)).slice().sort((a,b)=>String(a.date).localeCompare(String(b.date)));let cumulative=0;period.points=[];for(const x of rows){const start=period.from||d.periodStart,day=Math.max(0,(Date.parse(x.date)-Date.parse(start))/86400000);cumulative+=x.amount;period.points.push({day,value:cumulative,date:x.date})}const known=period.points.length?`<polyline points="${[[35,145],...period.points.map(p=>[xPos(p.day),yPos(p.value)])].map(x=>x.join(',')).join(' ')}" stroke="${colors[i%4]}" fill="none" stroke-width="2"/>`:'';const last=period.points.at(-1),end=32;return `${known}${period.forecast&&last?`<path d="M${xPos(last.day)} ${yPos(last.value)}L${xPos(end)} ${yPos(period.total)}" stroke="${colors[i%4]}" stroke-dasharray="4 4" fill="none"/>`:''}<circle cx="${xPos(end)}" cy="${yPos(period.total)}" r="4" fill="${colors[i%4]}"/>`}).join('');const saving=CashModel.saving(d);return `<div class="small">Бюджетный навигатор — Антон. Дневные линии строятся только по сохранённым операциям. Если известен лишь итог периода, показана точка; пунктир — прогноз.</div><div class="actions">${all.map(x=>`<button class="compact ${ids.includes(x.id)?'primary':''}" onclick="togglePeriod('${x.id}')">${esc(x.name)}</button>`).join('')}</div><svg id="budgetPlot" viewBox="0 0 350 180" role="img" aria-label="Сравнение периодов бюджета" style="touch-action:none" onpointerdown="this.setPointerCapture(event.pointerId);chartHover(event)" onpointermove="if(event.buttons)chartHover(event)"><path d="M35 15V145H325" stroke="#bbb" fill="none"/>${plots}<path id="plotCursor" d="M35 15V145" stroke="#aaa" stroke-dasharray="3 3"/><text x="35" y="167" font-size="10">15-е · начало</text><text x="260" y="167" font-size="10">15-е · конец</text></svg><div id="graphReadout" class="small">Проведите по графику для просмотра известных сумм.</div>${graphPeriods.length===2?item('Разница выбранных итогов',Number(graphPeriods[1].total)-Number(graphPeriods[0].total)):'<div class="small">Выберите два периода для сравнения.</div>'}<div class="gray">${editable('previousSpending','Расходы сравнительного периода')}${editable('savingGoal','Цель сокращения трат')}${editable('comparedSpending','Сценарий расходов')}${item('Предел расходов',saving.ceiling)}${item('Превышение',saving.excess,'red')}${item('Экономия следующего периода',saving.nextGoal)}<button class="compact" onclick="carryExcess()">Перенести превышение</button></div>`}
function chartHover(event){const svg=document.getElementById('budgetPlot'),bounds=svg.getBoundingClientRect(),x=Math.max(35,Math.min(320,(event.clientX-bounds.left)/bounds.width*350)),day=(x-35)/285*32;document.getElementById('plotCursor').setAttribute('d','M'+x+' 15V145');document.getElementById('graphReadout').textContent=graphPeriods.map(p=>{const point=p.points?.filter(x=>x.day<=day).at(-1);return p.name+': '+(point?fmt(point.value)+' на '+point.date:day>=31?fmt(p.total)+' · итог':'нет дневных данных')}).join(' · ')}
function openNextPeriod(){confirmSmall('Открыть следующий период? Сохраним историю; затем обновите баланс банка.',async()=>{try{if(d.balanceDate<d.periodEnd){showError('Сначала подтвердите закрытие периода','Введите банковский баланс после всех списаний последнего дня через карандаш. Это сохранит правильный переходящий остаток.');return}await Storage.backup('before-period-'+d.periodEnd,d);CashModel.archivePeriod(d);carryPendingBankPayments();const oldEnd=d.periodEnd;d.periodStart=new Date(Date.parse(oldEnd+'T12:00:00Z')+86400000).toISOString().slice(0,10);d.periodEnd=CashModel.addMonths(oldEnd,1);d.salaryStatus='expected';d.salaryActual=null;d.salaryReceivedDate='';d.limit=d.periodTargets[CashModel.goalKey(d)]??CashModel.strategic(d).current.balance;d.periodTargets[CashModel.goalKey(d)]=d.limit;d.carry=Number(d.nextPeriodCarry||0);d.nextPeriodCarry=0;d.statementTotal=0;d.statementStatus='Частичная выписка';d.statementDate=d.periodEnd;d.salaryDate=d.periodEnd.slice(0,8)+'07';d.rentDate=d.periodEnd;d.childDate=d.periodEnd.slice(0,8)+'01';d.loanActive=false;for(const key of ['rent','statement','alimony'])d.paymentStates[key]={};d.cibusIncluded=false;d.cibusActual=[];for(const x of d.subs){x.included_in_statement=false;const step=x.periodicity==='yearly'?12:1;let date=x.expected_charge_date||oldEnd;while(date<d.periodStart&&!['pending','unposted'].includes(x.bank_state))date=x.periodicity==='weekly'?new Date(Date.parse(date+'T12:00:00Z')+7*86400000).toISOString().slice(0,10):CashModel.addMonths(date,step);x.expected_charge_date=date}for(const x of d.installments){const schedule=CashModel.installmentSchedule(x);x.schedule=schedule;x.included_in_statement=false;if(schedule.length&&schedule.at(-1).date<d.periodStart&&!['pending','unposted'].includes(x.bank_state)){x.active=false;x.schedule_finished_at=d.periodStart}}await save('Открытие следующего периода');closeModal();render()}catch(e){showError('Период не изменён',e)}})}
function showPeriodSettings(){modal(`<h3>Расчётный период и даты</h3><p class="small">Личный credit: 15-е → 15-е. Семейный бюджет ведётся отдельно: 10-е → 9-е. Личные и семейные суммы автоматически не смешиваются.</p><button class="compact" onclick="openNextPeriod()">Открыть следующий период</button>${dateField('periodStart','Начало')}${dateField('periodEnd','Конец')}${dateField('salaryDate','Зарплата')}${dateField('childDate','Алименты')}<p class="small">Текущий баланс и его дату меняйте карандашом в верхней карточке. Кредит не переносится автоматически.</p><button class="compact" onclick="closeModal()">Закрыть</button>`)}
let pendingPurchaseEditor=null;
function editPurchase(key){legacyEditPurchase(key);const x=d.purchases.find(x=>x.id===key),body=document.querySelector('.modal');body.insertAdjacentHTML('beforeend',`<label>Категория<input id="editCategory" value="${esc(x.category||'Другое')}"></label><label>Способ оплаты<select id="editMethod">${['credit','debit','cash'].map(v=>`<option ${CashModel.method(x.method)===v?'selected':''}>${v}</option>`).join('')}</select></label>${editorCardHTML('editCard',x.cardId)}<div class="gray"><b>Банковское состояние</b><label><input id="editIncluded" type="checkbox" ${x.included_in_statement||['Включено в выписку','Списано со счёта'].includes(x.status)?'checked':''}> Уже в сумме credit</label><label><input id="editDebited" type="checkbox" ${x.bank_state==='debited'||x.status==='Списано со счёта'?'checked':''}> Списано банком</label><label>Дата проводки<input id="editPosted" type="date" value="${esc(x.posted_date||'')}"></label></div>`);if(x.document_id)body.insertAdjacentHTML('beforeend',`<div class="line"></div>${documentButton(x.document_id)}<span class="small"> Оригинальный чек</span>`);if(x.receipt_items?.length)body.insertAdjacentHTML('beforeend',`<details class="help" open><summary>Товары в чеке (${x.receipt_items.length})</summary><button class="compact" onclick="toggleSavedReceiptTranslation('${key}')">${x.ocr?.show_translation?'Оригинал':'Перевести'}</button>${receiptItemsHTML(x.receipt_items,x.ocr?.translations,x.ocr?.show_translation,true,key)}</details>`);if(x.ocr)body.insertAdjacentHTML('beforeend',`<details class="help"><summary>Исходный результат OCR</summary><pre dir="auto" style="white-space:pre-wrap">${esc(x.ocr.text||x.ocr.original?.text||'')}</pre></details>`);if(pendingPurchaseEditor?.key===key)for(const [field,value]of Object.entries(pendingPurchaseEditor.fields)){const input=document.getElementById(field);if(input)input.value=value}compactSelects(body)}
function savePurchase(key){const x=d.purchases.find(x=>x.id===key),name=document.getElementById('editName').value.trim(),amount=Number(document.getElementById('editAmount').value),date=document.getElementById('editDate').value,charge=document.getElementById('editCharge').value,posted=document.getElementById('editPosted').value,status=document.getElementById('editStatus').value,link=document.getElementById('editLink').value,included=document.getElementById('editIncluded').checked,debited=document.getElementById('editDebited').checked;if(!name||!Number.isFinite(amount)||amount<=0||!CashModel.validDate(date)||!CashModel.validDate(charge)||posted&&!CashModel.validDate(posted))return;if(status==='Запланировано'&&(included||debited))return showError('Проверьте статус','Запланированная покупка ещё не проведена банком');Object.assign(x,{name,amount,date,category:document.getElementById('editCategory').value.trim()||'Другое',method:document.getElementById('editMethod').value,cardId:document.getElementById('editCard').value,charge_date:charge,posted_date:posted,status,included_in_statement:document.getElementById('editMethod').value==='credit'&&included,bank_state:debited?'debited':included?'in_statement':'unposted',bank_debit_date:debited?charge:'',installment_id:d.installments.some(v=>v.id===link)?link:'',recurring_id:d.subs.some(v=>v.id===link)?link:'',lesson_payment_id:link.startsWith('lesson:')?link.slice(7):''});x.dog_entry_id=d.dogEntries.find(e=>!e.deleted&&x.category==='Собака / '+e.name)?.id||'';if(x.ocr)x.ocr.corrected={...(x.ocr.corrected||{}),name,amount,date,items:structuredClone(x.receipt_items||[]),confirmedAt:new Date().toISOString()};if(status==='Запланировано'){d.purchases=d.purchases.filter(v=>v!==x);d.planned.push(x)}pendingPurchaseEditor=null;save('Редактирование покупки и банковского состояния');closeModal();render()}
function editSavedReceiptItem(key,index){const x=d.purchases.find(x=>x.id===key),item=x.receipt_items[index];pendingPurchaseEditor={key,fields:Object.fromEntries(['editName','editAmount','editDate','editCharge','editStatus','editLink'].map(field=>[field,document.getElementById(field)?.value||'']))};modal(`<h3>Товар из сохранённого чека</h3><div class="form-row"><label>Название</label><input id="savedItemName" dir="auto" value="${esc(item.name)}"></div><div class="form-row"><label>Сумма, ₪</label><input id="savedItemAmount" type="number" step=".01" value="${item.amount}"></div><p class="small">Изменение товара не создаёт отдельное банковское списание. Итог покупки редактируется отдельно.</p><div class="actions"><button class="compact" onclick="editPurchase('${key}')">Отмена</button><button class="compact primary" onclick="saveSavedReceiptItem('${key}',${index})">Сохранить товар</button></div>`)}
function saveSavedReceiptItem(key,index){const x=d.purchases.find(x=>x.id===key),name=document.getElementById('savedItemName').value.trim(),amount=Number(document.getElementById('savedItemAmount').value);if(!name||!Number.isFinite(amount))return;Object.assign(x.receipt_items[index],{name,amount,corrected:true});if(x.ocr){x.ocr.translations=[];x.ocr.show_translation=false;}if(x.ocr)x.ocr.corrected={...(x.ocr.corrected||{}),items:structuredClone(x.receipt_items),confirmedAt:new Date().toISOString()};save('Исправление товара в чеке');editPurchase(key)}
function editable(key,label){if(key==='limit')return `<div class="row"><span>${label}</span><span class="field"><b class="money">${fmt(d.limit)}</b><button class="icon" onclick="editTarget()" aria-label="Изменить целевой минус">✎</button></span></div>`;if(key==='balance')return `<div class="row"><span>${label}</span><span class="field"><b class="money">${fmt(d.balance)}</b><button class="icon" onclick="editBankBalance()" aria-label="Изменить баланс банка">✎</button></span></div>`;return legacyEditable(key,label)}

let extraSpending=0,scenarioDate='',pendingPurchaseConfirm=null;
function summaryHTML(){const s=CashModel.scenario(d,extraSpending),bank=CashModel.bankSnapshot(d,new Date());return `<div class="top-summary"><h2>▣ Цель экономии — ${monthName()}</h2><span class="chip">${esc(d.statementStatus)}</span></div><div class="sub">${periodLabel()}</div><div class="grid summary-grid"><div><div class="sub">Расчётный дебет Save Cash</div><div class="bank-top-value"><b class="big ${bank.calculated<0?'red':'green'}" data-bank-calculated>${fmt(bank.calculated)}</b><button class="icon" onclick="editBankBalance()" aria-label="Изменить баланс банка">✎</button></div><div class="small">Подтверждённый баланс банка: <b data-bank-confirmed>${fmt(bank.confirmed)}</b> · ${esc(bank.confirmedDate)}</div></div><div>${obligationsHTML()}</div><div><div class="sub">${d.salaryStatus==='received'?'Зарплата поступила':'Ожидаемая зарплата'} · ${prettyDate(d.salaryReceivedDate||d.salaryDate)}</div>${scratch()}</div><div><div class="sub">Прогнозируемый запас до нуля</div><div class="big green scenario-zero">${fmt(s.zeroAvailable)}</div></div></div>${s.otherIncome?item('Другие будущие поступления',s.otherIncome):''}${forecastDetailsHTML()}<div class="bank-calendar-warning">Возможны дополнительные списания · проценты и комиссии уточняются по банку. Неизвестная сумма не начисляется.</div>${marginHTML(s)}${debtScaleHTML()}${scenarioHTML()}<div class="line"></div>${item('Прогноз после всех резервов',s.forecast,s.forecast>=0?'green':'red').replace('money ','money scenario-forecast ')}<div class="note">Прогноз по известным статьям. Частичную выписку и спорные операции необходимо сверить. Запасы до нуля и до цели не складываются.</div>`}
function marginHTML(s=CashModel.calculate(d)){return `<div class="target-margin"><div class="sub">Прогнозируемый запас до цели ${fmt(d.limit)} <button class="icon" onclick="editTarget()" aria-label="Изменить целевой минус">✎</button></div><div class="big green scenario-target">${fmt(s.targetAvailable)}</div><div class="zero-gap"><div class="sub">Не хватает до полного нуля</div><div class="big red scenario-zero-shortfall">${fmt(s.zeroShortfall)}</div></div><div class="small red scenario-shortfalls">${s.zeroShortfall?'До нуля не хватает '+fmt(s.zeroShortfall):''}${s.targetShortfall?' · До цели не хватает '+fmt(s.targetShortfall):''}</div><div class="small scenario-note" ${extraSpending?'':'hidden'}>Сценарий дополнительной покупки — ещё не записан в журнал</div></div>`}
function obligationsHTML(){const applied=new Set(CashModel.bankSnapshot(d,new Date()).movements.map(x=>x.row_id)),groups=CashModel.obligationGroups(d,TODAY()).map(g=>({...g,rows:g.rows.map(x=>({...x,calculated_applied:applied.has(x.id)})),total:g.rows.reduce((n,x)=>n+(applied.has(x.id)?0:CashModel.cents(x.contribution)),0)/100})),total=sum(groups.map(x=>({amount:x.total})));return `<details class="obligations-tree"><summary><span class="sub">Обязательные платежи</span><b class="big">${fmt(total)}</b></summary><div class="obligations-groups">${groups.map(g=>`<details class="gray obligation-group"><summary><span>${esc(g.name)}</span><b>${fmt(g.total)}</b></summary>${g.rows.map(x=>`<div class="obligation-item"><span>${esc(x.name)}<small>${esc(x.date)} · ${x.calculated_applied?'Учтено в расчётном дебете — банковский факт отдельно':x.included?'Уже учтено — дополнительно 0 ₪':esc(x.method)}</small></span><span class="money">${fmt(x.amount)}<button class="icon" onclick="editLedgerRow('${esc(x.id)}')" aria-label="Изменить ${esc(x.name)}">✎</button></span></div>`).join('')}</details>`).join('')||'<div class="small">Предстоящие обязательства не добавлены</div>'}<button class="compact" onclick="editFixedPayment()">＋ Обязательство</button></div></details>`}
function editTarget(){const preset=[2000,4000,6000],value=Math.abs(d.limit),custom=!preset.includes(value);modal(`<h3>Изменить целевой минус</h3><div class="target-choices">${preset.map(v=>`<label><input type="radio" name="target" value="${v}" ${v===value?'checked':''} onchange="toggleCustomTarget()">−${v.toLocaleString('ru-RU')} ₪</label>`).join('')}<label><input type="radio" name="target" value="custom" ${custom?'checked':''} onchange="toggleCustomTarget()">Свой вариант</label></div><div id="targetCustomWrap" ${custom?'':'hidden'}><label for="targetCustom">Величина долга, ₪</label><input id="targetCustom" type="number" inputmode="decimal" min="0" max="10000000" step=".01" value="${value}"></div><p class="small">Минус добавляется автоматически. Стратегическая цель на 15.01.2027 — 0 ₪.</p><div id="targetError" class="small red"></div><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="saveTarget()">Сохранить</button></div>`)}
function toggleCustomTarget(){document.getElementById('targetCustomWrap').hidden=document.querySelector('input[name="target"]:checked')?.value!=='custom'}
function saveTarget(){try{const choice=document.querySelector('input[name="target"]:checked')?.value;if(!choice)throw Error('Выберите цель');const raw=choice==='custom'?document.getElementById('targetCustom').value:choice;if(raw.trim()==='')throw Error('Введите величину долга');CashModel.setTarget(d,Number(raw));save('Изменение цели текущего периода');closeModal();render()}catch(e){document.getElementById('targetError').textContent=e.message}}
function scenarioHTML(){return `<div class="scenario-control"><label for="extraSpend">Дополнительная покупка · сценарий</label><div class="row"><input id="extraSpend" type="range" min="0" max="15000" step="10" value="${extraSpending}" oninput="updateScenario(this.value)"><output id="extraSpendValue">${fmt(extraSpending)}</output></div><input id="extraSpendNumber" type="number" inputmode="decimal" min="0" step=".01" value="${extraSpending}" aria-label="Сумма предполагаемой покупки" oninput="updateScenario(this.value)"><div id="scenarioWave">${waveHTML()}</div><p class="small">Проверка не создаёт покупку. Расходы по дням показаны отдельно от шкалы долга.</p></div>`}
function updateScenario(value){const n=Number(value);if(!Number.isFinite(n)||n<0)return;extraSpending=n;const s=CashModel.scenario(d,n);document.querySelectorAll('.big.scenario-forecast').forEach(x=>{x.classList.toggle('red',s.forecast<0);x.classList.toggle('green',s.forecast>=0)});for(const [cls,v]of [['scenario-zero',s.zeroAvailable],['scenario-zero-shortfall',s.zeroShortfall],['scenario-target',s.targetAvailable],['scenario-forecast',s.forecast]])document.querySelectorAll('.'+cls).forEach(x=>x.textContent=fmt(v));document.querySelectorAll('.scenario-shortfalls').forEach(x=>x.textContent=(s.zeroShortfall?'До нуля не хватает '+fmt(s.zeroShortfall):'')+(s.targetShortfall?' · До цели не хватает '+fmt(s.targetShortfall):''));document.querySelectorAll('.scenario-note').forEach(x=>x.hidden=!n);document.querySelectorAll('.debt-scale').forEach(scale=>{scale.outerHTML=debtScaleHTML()});document.getElementById('extraSpendValue').textContent=fmt(n);if(document.activeElement?.id!=='extraSpendNumber')document.getElementById('extraSpendNumber').value=n;document.getElementById('extraSpend').value=n;document.getElementById('scenarioWave').innerHTML=waveHTML()}
function waveHTML(){const selected=scenarioDate||TODAY(),count=Math.max(1,(Date.parse(d.periodEnd)-Date.parse(d.periodStart))/86400000),rows=CashModel.unique(d.purchases).filter(x=>CashModel.inPeriod(d,x.date)&&CashModel.belongs(d,x));let total=0;const points=[{day:0,value:0}];for(const date of [...new Set(rows.map(x=>x.date))].sort()){total+=sum(rows.filter(x=>x.date===date));points.push({day:(Date.parse(date)-Date.parse(d.periodStart))/86400000,value:total})}const max=Math.max(1,total+extraSpending),x=v=>20+v/count*300,y=v=>100-v/max*80;let path=points.length>1?'M'+x(points[0].day)+' '+y(points[0].value):'';for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],mid=(x(a.day)+x(b.day))/2;path+=` C${mid} ${y(a.value)},${mid} ${y(b.value)},${x(b.day)} ${y(b.value)}`}const day=Math.max(0,Math.min(count,(Date.parse(selected)-Date.parse(d.periodStart))/86400000)),list=rows.filter(v=>v.date===selected);return `<svg viewBox="0 0 340 125" aria-label="Волна фактических расходов и сценарий" role="img"><path d="M20 105H325" stroke="#ddd"/>${path?`<path d="${path}" stroke="#168356" fill="none" stroke-width="2"/>`:'<text x="20" y="45" font-size="11">Нет дневных операций</text>'}<path d="M${x(points.at(-1).day)} ${y(total)} L320 ${y(total+extraSpending)}" stroke="#ff8a00" stroke-dasharray="4 4" fill="none"/><path d="M${x(day)} 10V105" stroke="#888" stroke-dasharray="2 3"/><text x="${Math.min(310,x(day))}" y="120" font-size="11">▼ ${selected.slice(8)}</text></svg><label class="small">Выбранный день <input type="date" value="${esc(selected)}" min="${d.periodStart}" max="${d.periodEnd}" onchange="scenarioDate=this.value;document.getElementById('scenarioWave').innerHTML=waveHTML()"></label><ul class="day-expenses">${list.map(v=>`<li><span>${esc(v.name)}</span><b>${fmt(v.amount)}</b></li>`).join('')||'<li class="small">Покупок за выбранный день нет</li>'}</ul>${bankDayHTML(selected)}`}
function bankDayHTML(date){const rows=CashModel.ledger(d).filter(x=>(['loan','rent','alimony','statement'].includes(x.id)||x.ref?.key==='rent')&&x.date===date&&x.amount&&!(x.id==='loan'&&d.paymentStates.loan?.included_in_statement));return rows.length?`<details class="small" open><summary>Банковские списания выбранного дня</summary>${rows.map(x=>`<div class="row"><span>${esc(x.name)} · ${x.included?'учтено в подтверждённом снимке':x.actual_date?'подтверждено, ожидает нового снимка':'ожидается подтверждение'}</span><b>${fmt(x.amount)}</b></div>`).join('')}<p class="small">Покупки и списания карты показаны отдельно; они не складываются повторно в прогнозе.</p></details>`:''}
function showSalaryEditor(){modal(`<h3>Зарплата</h3><label>Ожидаемая сумма, ₪</label><input id="newSalary" type="number" min="0" step=".01" inputmode="decimal" value="${d.salary}"><label>Ожидаемая дата</label><input id="newSalaryDate" type="date" value="${d.salaryDate}"><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="saveSalary()">Сохранить прогноз</button></div><div class="line"></div><div class="small">${d.salaryStatus==='received'?'Поступило '+fmt(d.salaryActual)+' · '+esc(d.salaryReceivedDate):'Ещё ожидается'}</div><button class="compact" onclick="salaryReceiptEditor()">Зарплата поступила</button><button class="compact" onclick="showIncomes()">Другие поступления</button><details><summary>История зарплаты</summary>${(d.salaryHistory||[]).map(x=>`<div class="small">${esc(x.at)} · ${fmt(x.actual??x.expected)}</div>`).join('')||'<p class="small">Изменений нет</p>'}</details>`)}
function salaryReceiptEditor(){modal(`<h3>Зарплата поступила</h3><label>Фактическая сумма, ₪</label><input id="salaryActual" type="number" min="0" step=".01" value="${d.salaryActual??d.salary}"><label>Дата поступления</label><input id="salaryReceivedDate" type="date" value="${TODAY()}"><label>Баланс банка после поступления, ₪</label><input id="salaryAfterBalance" type="number" step=".01"><label>Баланс актуален на</label><input id="salaryAfterDate" type="date" value="${TODAY()}"><p class="small">Вместе фиксируются поступление и актуальный баланс. Зарплата не добавляется к нему второй раз.</p><div id="salaryReceiptError" class="small red"></div><div class="actions"><button class="compact" onclick="showSalaryEditor()">Назад</button><button class="primary compact" onclick="saveSalaryReceipt()">Подтвердить поступление</button></div>`)}
function saveSalaryReceipt(){try{if(document.getElementById('salaryReceivedDate').value>TODAY())throw Error('Поступление не может быть в будущем');if(document.getElementById('salaryAfterBalance').value==='')throw Error('Укажите баланс после поступления');CashModel.receiveSalary(d,Number(document.getElementById('salaryActual').value),document.getElementById('salaryReceivedDate').value,Number(document.getElementById('salaryAfterBalance').value),document.getElementById('salaryAfterDate').value);save('Фактическое поступление зарплаты');closeModal();render()}catch(e){document.getElementById('salaryReceiptError').textContent=e.message}}
function editFixedPayment(key=''){const x=d.fixedPayments.find(x=>x.id===key)||{name:'',amount:0,planned_date:d.periodEnd,owner:'anton',method:'debit'};modal(`<h3>Обязательный платёж</h3><label>Название<input id="fixedName" value="${esc(x.name)}"></label><label>Сумма, ₪<input id="fixedAmount" type="number" min="0" step=".01" value="${x.amount}"></label><label>Уже оплачено из этой суммы, ₪<input id="fixedPaidAmount" type="number" min="0" step=".01" value="${x.paid_amount||0}"></label><label>Плановая дата<input id="fixedDate" type="date" value="${esc(x.planned_date||x.charge_date||x.date)}"></label><label class="small"><input id="fixedDebited" type="checkbox" ${x.bank_state==='debited'?'checked':''}> Списание подтверждено банком</label><label>Фактическая дата<input id="fixedActualDate" type="date" value="${esc(x.actual_debit_date||'')}"></label><label class="small"><input id="fixedReflected" type="checkbox" ${x.balance_reflected===true||x.balance_reflected===undefined&&x.bank_state==='debited'&&x.actual_debit_date<=d.balanceDate?'checked':''}> Уже отражено в подтверждённом балансе</label><label>Плательщик<select id="fixedOwner">${[['anton','Антон'],['family','Семейный бюджет'],['sasha','Саша']].map(([v,l])=>`<option value="${v}" ${x.owner===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Оплата<select id="fixedMethod">${['debit','credit','cash'].map(m=>`<option ${x.method===m?'selected':''}>${m}</option>`).join('')}</select></label><label class="small"><input id="fixedIncluded" type="checkbox" ${x.included_in_statement?'checked':''}> Входит в общую сумму credit</label><div id="fixedError" class="small red"></div><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="saveFixedPayment('${key}')">Сохранить</button></div>`)}
function saveFixedPayment(key=''){const paidAmount=Number(document.getElementById('fixedPaidAmount').value);const name=document.getElementById('fixedName').value.trim(),raw=document.getElementById('fixedAmount').value,amount=Number(raw),date=document.getElementById('fixedDate').value,debited=document.getElementById('fixedDebited').checked,actual=document.getElementById('fixedActualDate').value,reflected=document.getElementById('fixedReflected').checked;if(!Number.isFinite(paidAmount)||paidAmount<0||paidAmount>amount||!name||raw===''||!Number.isFinite(amount)||amount<0||!CashModel.validDate(date)||debited&&(!CashModel.validDate(actual)||actual>TODAY())||reflected&&(!debited||actual>d.balanceDate)){document.getElementById('fixedError').textContent='Проверьте сумму и даты; списание должно быть подтверждено и входить в снимок банка';return}const old=d.fixedPayments.find(x=>x.id===key),values={...(old||{}),id:key||id(),name,amount,paid_amount:paidAmount,date,planned_date:date,charge_date:date,owner:document.getElementById('fixedOwner').value,method:document.getElementById('fixedMethod').value,included_in_statement:document.getElementById('fixedIncluded').checked,bank_state:debited?'debited':'pending',actual_debit_date:debited?actual:'',balance_reflected:reflected,source:'Подтверждено пользователем'};if(old)d.featureHistory.push({id:id(),at:new Date().toISOString(),event:'Изменение банковского обязательства',before:structuredClone(old)});if(old)Object.assign(old,values);else d.fixedPayments.push(values);save('Обязательный платёж');closeModal();render()}

function receiptItemsHTML(items,translations=[],show=false,editable=false,key=''){return items.map((x,i)=>{const translated=translations.find(v=>v.id===x.id),name=ReceiptTranslation.label(x,translations,show);return `<div class="receipt-item"><span dir="auto">${esc(name)}${x.quantity!==undefined?`<small> × ${x.quantity}${x.quantity_review?' · количество проверить':''}</small>`:''}${x.review||show&&translated?.review?'<small class="red">Нужна проверка</small>':''}</span><span>${fmt(x.amount)}${editable?`<button class="icon" onclick="${key?`editSavedReceiptItem('${key}',${i})`:`editReceiptItem(${i},false)`}">✎</button>`:''}</span></div>`}).join('')}
async function toggleReceiptTranslation(external=false){const r=receiptDraft.ocr;if(r.show_translation){r.show_translation=false;updateReceiptView();return}if(r.translations?.length===r.items.length){r.show_translation=true;updateReceiptView();return}try{r.translations=await ReceiptTranslation.translate(r.items,{allowExternal:external});r.show_translation=true;updateReceiptView();if(!external&&r.translations.some(x=>x.source==='unavailable'))document.getElementById('ocrDraftContainer').insertAdjacentHTML('beforeend','<p class="small">Для части названий нет локального перевода. <button class="compact" onclick="offerCloudTranslation()">Перевести остальные онлайн</button></p>')}catch(e){showError('Перевод не завершён',e)}}
function offerCloudTranslation(){modal(`<h3>Перевести названия онлайн?</h3><p class="small">Внешнему сервису MyMemory будут переданы только названия товаров, без фотографии, цен и реквизитов. Перевод нужно проверить. Неуверенный OCR сначала исправьте. Для локального перевода интернет не нужен.</p><div class="actions"><button class="compact" onclick="closeModal()">Отмена</button><button class="primary compact" onclick="closeModal();receiptDraft.ocr.translations=[];toggleReceiptTranslation(true)">Разрешить перевод названий</button></div>`)}
function confirmPurchaseSave(){const x=pendingPurchaseConfirm;if(!x||!['Совершено','Запланировано'].includes(x.status))return;const error=document.getElementById('purchaseConfirmationError');if(!error)return;const status=x.status,charge=document.getElementById('purchaseCharge')?.value||CashModel.chargeDate(x,d),posted=document.getElementById('purchasePosted')?.value||'',debited=document.getElementById('purchaseDebited')?.checked||false,included=document.getElementById('purchaseIncluded')?.checked||false;if(!CashModel.validDate(charge)||debited&&charge>TODAY()||posted&&!CashModel.validDate(posted)){error.textContent='Проверьте даты банковской проводки и списания';return}Object.assign(x,{posted_date:posted,charge_date:charge,bank_debit_date:debited?charge:'',bank_state:debited?'debited':included?'in_statement':'unposted',included_in_statement:x.method==='credit'&&included});if(status==='Запланировано')d.planned.push(x);else{BudgetFeatures.attachInstallment(d,x);d.purchases.push(x)}purchaseInstallments=0;pendingPurchaseConfirm=null;receiptDraft=null;draftAttachment=null;closeModal();save('Подтверждена покупка: '+status);render();document.getElementById('receiptNotice').textContent=status==='Запланировано'?'План сохранён':'Покупка сохранена'}

async function toggleSavedReceiptTranslation(key){const x=d.purchases.find(x=>x.id===key);x.ocr??={};pendingPurchaseEditor={key,fields:Object.fromEntries(['editName','editAmount','editDate','editCharge','editStatus','editLink','editPosted'].map(field=>[field,document.getElementById(field)?.value||'']))};if(!x.ocr.show_translation)x.ocr.translations=await ReceiptTranslation.translate(x.receipt_items);x.ocr.show_translation=!x.ocr.show_translation;await save('Переключение перевода чека');editPurchase(key)}
function backOneLevel(){if(document.querySelector('.modal')){closeModal();return}if(currentView!=='home'){goView('home');return}window.scrollTo({top:0,behavior:'smooth'})}
function ledgerAmount(collection,kind){return sum(CashModel.calculate(d).rows.filter(x=>!x.included&&(collection?x.ref?.collection===collection:x.kind===kind)))}
function lowerSummaryHTML(){const s=CashModel.calculate(d);return `<h2>▣ Цель экономии — ${monthName()}</h2>${item('Уже потрачено · покупки периода',purchasesCash()+purchasesCard())}<div class="grid"><div><div class="sub">Ожидаемая / фактическая зарплата</div>${scratch()}</div><div><div class="sub">Прогнозируемый запас до нуля</div><div class="big green scenario-zero">${fmt(s.zeroAvailable)}</div></div></div>${forecastDetailsHTML()}${marginHTML(s)}${item('Расходы и резервы, ещё не в балансе',s.expenses)}${item('Прогноз после всех резервов',s.forecast,s.forecast>=0?'green':'red')}<div class="line"></div>${calculatorHTML()}${debtScaleHTML()}`}
function creditLoansHTML(){const bank=CashModel.bankSnapshot(d,new Date()),credit=CashModel.creditOverview(d,TODAY()),loan=credit.loan,loanStatus=!loan?'Не добавлен':d.paymentStates.loan?.included_in_statement?'Внутри общей суммы credit — отдельно 0 ₪':loan.included&&loan.date<=d.balanceDate?'Подтверждено балансом':d.paymentStates.loan?.bank_state==='debited'?'Подтверждено банком':loan.date<=TODAY()?'Срок наступил · ожидает подтверждения':'Ожидается';return `<div class="gray">${item('Известные операции по картам · неполный итог',credit.accumulated)}<div class="small">Сумма известных выписок и покупок до сегодняшнего дня вне них. ${credit.partial?'Выписка частичная — итог неполный.':''} Это не дополнительное вычитание.</div>${cardTotalsHTML(credit)}</div><div class="gray">${loan?`${item('Кредит · отдельный платёж',loan.amount)}<div class="small">Дата списания: ${esc(loan.date)} · ${loanStatus}</div>${paymentStateButton('loan')}`:'<div class="small">Отдельный платёж кредита не добавлен</div>'}</div>${bankCalendarHTML()}${bank.movements.length?`<details class="gray"><summary>Расчётно учтено к ${esc(TODAY())}: ${fmt(bank.deductions)}</summary>${bank.movements.map(x=>`<div class="row"><span>${esc(x.name)}<small> · ${esc(x.date)}</small></span><b>${fmt(x.amount)}</b></div>`).join('')}<p class="small">Подтверждённый банковский снимок не изменён. Обновите баланс через карандаш, когда сверите банк.</p></details>`:''}<details class="help"><summary>Выписки и входящие операции</summary>${[...credit.envelopes,...credit.covered,...credit.independent].map(x=>`<div class="obligation-item"><span>${esc(x.name)}<small>${esc(x.date)} · ${x.kind==='statement'?'Общая сумма выписки':x.included?'Внутри выписки — дополнительно 0 ₪':'Вне выписки'}${credit.reserved.includes(x)?' · будущая статья':''}</small></span><b>${fmt(x.amount)}</b></div>`).join('')||'Операций пока нет'}</details>${credit.unverified.length?`<details class="help" open><summary>Требуют сверки · не добавлены к нагрузке</summary>${credit.unverified.map(x=>`<div class="obligation-item"><span>${esc(x.name)}<small>${esc(x.date)}</small></span><span>${fmt(x.amount)}<button class="icon" onclick="editLedgerRow('${esc(x.id)}')">✎</button><button class="icon danger" aria-label="Удалить запись" onclick="deleteUnverified('${esc(x.id)}')">×</button></span></div>`).join('')}</details>`:''}`}
function refreshFinancialDate(){const today=TODAY();if(today===financialRenderedDay||document.querySelector('.modal')||['INPUT','TEXTAREA'].includes(document.activeElement?.tagName))return;financialRenderedDay=today;const form=Object.fromEntries(['shop','amount','date','category','customCategory'].map(k=>[k,document.getElementById(k)?.value||''])),manual=document.getElementById('category')?.dataset.manual==='true',method=pay;render();for(const[k,value]of Object.entries(form)){const input=document.getElementById(k);if(input)input.value=value}if(form.category)setPurchaseCategory(form.category,manual);choosePay(method)}
let financialRenderedDay=TODAY();window.addEventListener('focus',refreshFinancialDate);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshFinancialDate()});setInterval(refreshFinancialDate,30000);
function paymentStateButton(key){return `<button class="compact" onclick="editPaymentState('${key}')">Статус по банку: ${{pending:'ещё не списано',debited:'списано'}[d.paymentStates[key]?.bank_state]||'по дате баланса'} ✎</button>`}
function editPaymentState(key){const value=d.paymentStates[key]?.bank_state||'legacy';modal(`<h3>Банковское списание</h3>${key==='loan'?`<label><input id="loanInStatement" type="checkbox" ${d.paymentStates.loan?.included_in_statement?'checked':''}> Этот платёж уже внутри общей суммы credit</label>`:''}<select id="directBankState"><option value="legacy" ${value==='legacy'?'selected':''}>Сопоставлять по дате баланса</option><option value="pending" ${value==='pending'?'selected':''}>Ещё не списано — в том числе просроченное</option><option value="debited" ${value==='debited'?'selected':''}>Списано банком</option></select><label>Фактическая дата списания<input id="directBankDate" type="date" value="${esc(d.paymentStates[key]?.actual_debit_date||'')}"></label><label class="small"><input id="directReflected" type="checkbox" ${d.paymentStates[key]?.balance_reflected===true||d.paymentStates[key]?.balance_reflected===undefined&&d.paymentStates[key]?.bank_state==='debited'&&d.paymentStates[key]?.actual_debit_date<=d.balanceDate?'checked':''}> Уже отражено в подтверждённом балансе</label><p class="small">При отметке «Ещё не списано» обязательство остаётся в прогнозе после срока оплаты. Списанный платёж исключается только если его дата уже отражена в банковском балансе.</p><div id="directBankError" class="small red"></div><div class="actions"><button onclick="closeModal()">Отмена</button><button class="primary" onclick="savePaymentState('${key}')">Сохранить</button></div>`)}
function savePaymentState(key){const bank_state=document.getElementById('directBankState').value,actual_debit_date=document.getElementById('directBankDate').value;if(bank_state==='debited'&&(!CashModel.validDate(actual_debit_date)||actual_debit_date>TODAY())){document.getElementById('directBankError').textContent='Укажите фактическую дату';return}const balance_reflected=bank_state==='legacy'?undefined:bank_state==='debited'?document.getElementById('directReflected').checked:false;if(balance_reflected&&actual_debit_date>d.balanceDate){document.getElementById('directBankError').textContent='Сначала обновите банковский баланс на дату после списания';return}d.paymentStates[key]={bank_state,balance_reflected,actual_debit_date:bank_state==='debited'?actual_debit_date:'',included_in_statement:key==='loan'&&document.getElementById('loanInStatement')?.checked===true};save('Статус банковского списания');closeModal();render()}
function showIncomes(){modal(`<h3>Другие поступления</h3>${d.incomes.filter(x=>!x.deleted).map(x=>`<div class="row"><span>${esc(x.name)}<small>${esc(x.date)} · ${esc(x.owner||'anton')}</small></span><b>${fmt(x.amount)}<button class="icon" onclick="editIncome('${x.id}')">✎</button><button class="icon danger" onclick="confirmSmall('Удалить поступление?',()=>{CashModel.removeRecord(d,{collection:'incomes',id:'${x.id}'});save('Удалено поступление');showIncomes()})">×</button></b></div>`).join('')||'<p class="small">Дополнительных поступлений нет</p>'}<button class="compact" onclick="editIncome()">＋ Поступление</button><button class="compact" onclick="showSalaryEditor()">Назад</button>`)}
function editIncome(key=''){const x=d.incomes.find(x=>x.id===key)||{name:'',amount:0,date:d.salaryDate,owner:'anton'};modal(`<h3>Поступление</h3><label>Название<input id="incomeName" value="${esc(x.name)}"></label><label>Сумма, ₪<input id="incomeAmount" type="number" min="0" step=".01" value="${x.amount}"></label><label>Дата поступления в банк<input id="incomeDate" type="date" value="${x.date}"></label><label>Получатель<select id="incomeOwner"><option value="anton" ${x.owner==='anton'?'selected':''}>Антон</option><option value="sasha" ${x.owner==='sasha'?'selected':''}>Саша</option><option value="family" ${x.owner==='family'?'selected':''}>Семейный бюджет</option></select></label><p class="small">В прогноз Антона попадают только его поступления, ещё не отражённые в балансе. Если дата уже прошла, а деньги не поступили — уточните ожидаемую дату по банку. Ввод не меняет подтверждённый баланс.</p><div class="actions"><button onclick="showIncomes()">Назад</button><button class="primary" onclick="saveIncome('${key}')">Сохранить</button></div>`)}
function saveIncome(key){const name=document.getElementById('incomeName').value.trim(),amount=Number(document.getElementById('incomeAmount').value),date=document.getElementById('incomeDate').value;if(!name||!Number.isFinite(amount)||amount<0||!CashModel.validDate(date))return;const old=d.incomes.find(x=>x.id===key),value={id:key||id(),name,amount,date,owner:document.getElementById('incomeOwner').value,source:'Введено пользователем'};if(old)Object.assign(old,value);else d.incomes.push(value);save('Уточнение поступления');closeModal();render()}
if("serviceWorker" in navigator){window.addEventListener("load",()=>navigator.serviceWorker.register("./sw.js").then(r=>swRegistration=r).catch(e=>{const n=document.getElementById("storage-state");if(n)n.textContent="Офлайн-режим недоступен: "+e.message}))}
window.visualViewport?.addEventListener('resize',()=>document.documentElement.style.setProperty('--viewport-height',window.visualViewport.height+'px'));
start();

function reviewInstallment(key){const x=d.installments.find(x=>x.id===key);if(!x)return;const evidence=CashModel.installmentEvidence(d,x);confirmSmall('Подтвердить '+x.merchant+' · '+fmt(x.amount_per_payment)+' · '+x.payment_index+'/'+x.payment_count+' · '+x.expected_charge_date+'? '+(evidence.length?'Найдено соответствие в импортированной выписке.':'Точного соответствия нет. Подтверждайте только после проверки оригинала банка.'),()=>{CashModel.confirmInstallment(d,key,evidence[0]||{manual:true});save('Рассрочка подтверждена без изменения суммы');render()})}
